function w(e){return e.trim().toLowerCase().replace(/[^a-z0-9]/g,"")}function T(e,t){if(e.kind==="balance")return Object.entries(e.solution).every(([r,i])=>{const l=t.answers[r]?.trim();return!!l&&Number.isFinite(Number(l))&&Number(l)===Number(i)});if(e.kind==="ledger"||e.kind==="cipher")return Object.entries(e.solution).every(([r,i])=>w(t.answers[r]||"")===w(i));if(e.kind==="sequence")return(t.order||[]).join("|")===e.solution.join("|");if(e.kind==="circuit"){const r=t.lamps||e.initial;return r.length===e.size*e.size&&e.target.length===r.length&&r.every((i,l)=>i===e.target[l])}const a=t.route||[e.start];if(a[0]!==e.start||a.at(-1)!==e.end||a.length-1>e.maxSteps||new Set(a).size!==a.length)return!1;let n=0;for(let r=0;r<a.length;r++){const i=a[r];if(i<0||i>=e.width*e.height||e.blocked.includes(i))return!1;if(i===e.waypoints[n])n++;else if(e.waypoints.includes(i))return!1;if(r>0){const l=a[r-1];if(Math.abs(Math.floor(i/e.width)-Math.floor(l/e.width))+Math.abs(i%e.width-l%e.width)!==1)return!1}}return n===e.waypoints.length}function u(e,t,a){const n=Math.floor(t/a),r=t%a,i=[t];return n>0&&i.push(t-a),n<a-1&&i.push(t+a),r>0&&i.push(t-1),r<a-1&&i.push(t+1),e.map((l,m)=>i.includes(m)?!l:l)}const A={kind:"ledger",rows:[{id:"vellum",title:"Vellum · counter 1"},{id:"fen",title:"Fen · counter 2"},{id:"silt",title:"Silt · counter 3"},{id:"rook",title:"Rook · counter 4"},{id:"moss",title:"Moss · counter 5"}],columns:[{id:"seal",title:"Seal",options:["Blue Thread","Copper Leaf","White Eye","Green Door","Black Bell"]},{id:"error",title:"Recorded defect",options:["Missing name","Reversed date","Duplicate kiss","Blank address","Absent witness"]}],solution:{"vellum.seal":"Green Door","vellum.error":"Absent witness","fen.seal":"Copper Leaf","fen.error":"Blank address","silt.seal":"Black Bell","silt.error":"Reversed date","rook.seal":"Blue Thread","rook.error":"Duplicate kiss","moss.seal":"White Eye","moss.error":"Missing name"}},x={kind:"cipher",inscription:"3:1 3:2 3:3 4:3  |  1:5 6:1 2:2 5:1 1:2 6:8 5:4 4:4 5:1  |  1:1 6:2 7:7 7:1 1:3 4:5 6:6 2:2",fields:[{id:"action",label:"Instruction"},{id:"subject",label:"Subject"},{id:"detail",label:"Where to look"}],solution:{action:"READ",subject:"THE WILLOW",detail:"FOOTNOTE"}},E={kind:"balance",fields:[{id:"elin",label:"Elin's unspent afternoon",min:0,max:93,suffix:"minutes"},{id:"library",label:"Library handling reserve",min:0,max:93,suffix:"minutes"},{id:"collector",label:"Collector's allowance",min:0,max:93,suffix:"minutes"},{id:"ward",label:"Ward's future holding",min:0,max:93,suffix:"minutes"},{id:"gate",label:"Threshold deposit",min:0,max:93,suffix:"minutes"}],equations:["Elin + Library = 40","Library + Threshold = 30","Ward = Elin + 6","Elin = 2 × Collector + 1","All five accounts total 93","Ward + Library = 46 (cross-check)"],solution:{elin:"23",library:"17",collector:"11",ward:"29",gate:"13"}},S={kind:"sequence",cards:[{id:"notice",title:"The correction notice",description:"Elin is told an afternoon already elapsed."},{id:"erase",title:"The name is removed",description:"The public index stops admitting Elin existed."},{id:"copy",title:"Pip copies the verse",description:"The moth copies words Elin pointed out."},{id:"appeal",title:"Vellum files an appeal",description:"A fox puts his own name beneath an objection."},{id:"borrow",title:"The book is borrowed",description:"Elin signs for a book about tomorrow."},{id:"freeze",title:"The Hospital receives Elin",description:"Nurse Reed records an interrupted breath."},{id:"inspect",title:"The collector's inspection",description:"An Aristobat finds an unapproved blank line."}],solution:["borrow","copy","inspect","notice","appeal","freeze","erase"]},R={kind:"route",width:7,height:7,blocked:[5,6,23,34,36,37,38,39,44,45,46,47],start:0,end:48,waypoints:[9,31,12,40],maxSteps:24,solution:[0,1,2,9,16,15,14,21,28,29,30,31,24,17,18,19,12,13,20,27,26,33,40,41,48]};function k(e,t){const a=Array.from({length:25},(r,i)=>e.includes(i));return{kind:"circuit",size:5,initial:t.reduce((r,i)=>u(r,i,5),a),target:a,solution:t}}const C=k([10,11,12,13,14],[0,3,6,8,10,13,17,20,22,24]),I={kind:"ledger",rows:[{id:"apricot",title:"Apricot crate"},{id:"pear",title:"Pear crate"},{id:"millet",title:"Millet crate"},{id:"willow",title:"Willow crate"},{id:"plum",title:"Plum crate"}],columns:[{id:"destination",title:"Destination",options:["Hospital","Castle","Casino","Storehouse","Compost"]},{id:"charge",title:"Time charged to the grower",options:["4","7","10","13","16"]}],solution:{"apricot.destination":"Hospital","apricot.charge":"7","pear.destination":"Castle","pear.charge":"16","millet.destination":"Storehouse","millet.charge":"10","willow.destination":"Casino","willow.charge":"13","plum.destination":"Compost","plum.charge":"4"}},N={kind:"cipher",inscription:"DFS / SRDVQAF / RG / NJDF / SML / SRMJ",fields:[{id:"message",label:"The dispatch instruction, in ordinary words"}],solution:{message:"THE HARVEST IS HELD NOT LOST"}},B={kind:"balance",fields:[{id:"workers",label:"Orchard workers",min:0,max:72,suffix:"minutes"},{id:"patients",label:"Hospital patients",min:0,max:72,suffix:"minutes"},{id:"travellers",label:"Travellers",min:0,max:72,suffix:"minutes"},{id:"seeds",label:"Seed keepers",min:0,max:72,suffix:"minutes"},{id:"buffer",label:"Breakage reserve",min:0,max:72,suffix:"minutes"}],equations:["Patients = Workers + 6","Travellers = Workers − 3","Seeds = Workers ÷ 2","Breakage = Workers ÷ 3","The five allocations total 72","Patients + Travellers = 2 × Workers + 3 (cross-check)"],solution:{workers:"18",patients:"24",travellers:"15",seeds:"9",buffer:"6"}},P={kind:"sequence",cards:[{id:"seal",title:"The storehouse is sealed",description:"An Aristobat witnesses the final lock."},{id:"divide",title:"The harvest is divided",description:"Fruit is assigned to names not yet submitted."},{id:"discard",title:"The surplus is condemned",description:"Unclaimed plenty becomes official waste."},{id:"sow",title:"The seed is planted",description:"The gardener places a seed in borrowed soil."},{id:"collect",title:"Applications are collected",description:"Workers are finally allowed to ask for their fruit."},{id:"measure",title:"The crop is measured",description:"A clerk counts branches before there are blossoms."},{id:"permit",title:"Permits are printed",description:"The forms are dated after the allocation closes."}],solution:["sow","measure","divide","permit","collect","seal","discard"]},O={kind:"route",width:8,height:8,blocked:[5,11,13,14,22,33,36,38,39,41,47,49,50,51,52,53,54,55,57,58,59,60,61,62,63],start:56,end:6,waypoints:[18,20,45,7],maxSteps:29,solution:[56,48,40,32,24,16,17,18,10,2,3,4,12,20,28,27,26,34,42,43,44,45,37,29,30,31,23,15,7,6]},H=k([2,6,7,8,10,11,12,13,14,17,22],[1,4,5,7,11,12,15,18,21,23]);function o(e,t,a,n,r){return{id:e,title:t,task:a,board:n,hints:r,...M[e],minutes:{min:n.kind==="circuit"?4:3,typical:n.kind==="circuit"?7:5,max:9}}}const M={afternoon_ledger:{narrative:["The Library has been extended with two dead caravans. Between them, a tarpaulin bows under rainwater nobody has permission to tip away. Vellum leads you past drawers swollen shut around names the catalogue can no longer find. Pip carries a kettle with no lid. There is enough water for three shallow cups. At the last counter, a mouse’s name has been scraped off. The pale rectangle is the cleanest thing in the room.","“Elin passed through all five desks,” Vellum says. His counter is the first. Each desk certified a separate defect, then passed her on while her remaining afternoon thinned. “I thought somebody farther along would fix it.” Behind his spectacles, the skin around his eyes looks sore. The next window was always open. That was how they finished her.","The brass seals were removed during an audit. Their incident slips survived in a biscuit box somebody had used to keep out mice. Reunite seal and defect, and you can show how five ordinary signatures became an order to stop an ordinary body. Pip sets down the kettle. “Use their names,” he says. He does not say everyone was doing their best. Vellum does not ask him to. "],evidence:[{title:"Counter register",text:"Vellum worked counter 1, Fen counter 2, Silt counter 3, Rook counter 4, and Moss counter 5. Each used one distinct seal and certified one distinct defect. Every seal and defect in the options appears once. A record described as immediately after another belongs to the next counter, with none between."},{title:"Seal maintenance slip",text:"The replacement-seal register places Copper Leaf immediately after Green Door. Blue Thread was used at neither end of the five-counter line. White Eye was used two counters after Black Bell; exactly one counter stood between them."},{title:"Incident cross-reference",text:"White Eye marked the missing-name record. Black Bell marked the reversed date. The duplicate-kiss certificate came immediately after the reversed date, and the blank-address certificate immediately before it. These are the recorded defects, including ones a preceding desk may have caused."},{title:"Witness's remaining sentence",text:"The absent-witness certificate was issued somewhere before the blank-address certificate. The retained statement has therefore crossed out. It gives a positional relation, not an excuse. There were no additional defects outside the five listed."}],resolution:["Moss’s White Eye completed the deletion. Vellum’s absent-witness certificate began it; Fen, Silt, and Rook carried it onward through address, date, and kiss. Elin’s signature is the one they rubbed away. Vellum copies his own name into the appeal before the others and holds the pen still until his hand stops shaking. Pip pours the three cups almost to their bottoms. Nobody calls this forgiveness. In the drawer where a person used to be, the leak continues collecting water."]},afternoon_cipher:{narrative:["Moss’s certificate cites a footnote without identifying the book. Vellum brings out THE MANAGEMENT OF UNFINISHED DAYS. Its buckled boards smell of a room that never dries. A narrow strip of paper is stitched into the binding, its coordinates written so faintly that you have to hold them beside the defective window. Somebody tried to leave a thought where a form would not think to look.","Pip remembers Elin sitting with Nettle beneath the shelf heater, which had been disconnected but still bore a charge for warmth. She used to work through little puzzles after cleaning the roadside washrooms. “She liked an answer that stayed answered,” he says. That afternoon there was a drawing of a willow around an unfinished line. An Aristobat saw the blank before either mouse could finish reading. The file describes their interrupted reading as an inability to comprehend. ","Seven dictionary words remain on the endpaper. Display order made them easy to check; binding order made the hidden sentence harder to recognise at a glance. Nothing has to be guessed. Vellum lays the endpaper flat beneath two chipped saucers. “She wrote for somebody who would take the trouble,” he says. Find the sentence she hid. There are plenty of authorised accounts of Elin. This may be the last account still in her own hand."],evidence:[{title:"The seven endpaper words",text:"HOSPITAL · WILLOW · FINITE · TOMORROW · UNDOOR · READER · KETTLE. The surviving endpaper contains this complete dictionary. Use every printed word; letter case makes no difference and none contains a hidden space."},{title:"Binder's convention",text:"The binding convention sorts words by length, shortest first. Equal-length words go in ordinary alphabetical order. Number the resulting dictionary from 1, then number the letters inside each word from 1. Display order on the endpaper is not binding order."},{title:"Pip's careful copy",text:"For A:B, take dictionary word A and its letter B. Read the coordinates left to right. Each vertical bar ends one answer group. A group may spell more than one ordinary word; the marks between groups survived the inspection."}],resolution:["READ THE WILLOW FOOTNOTE. The passage argues that an unused moment remains its owner’s: a dormant branch has not forfeited spring. Elin underlined it once, carefully, as if another line might look demanding. Her afternoon sits intact in other people’s accounts while her body lies stopped in the Hospital. Pip keeps a finger on the drawn branch until Vellum asks to copy the evidence. The paper is soft along the edge where Elin held it. For a moment you can tell exactly where her hand used to be."]},afternoon_balance:{narrative:["The footnote points to an account sheet bearing Elin’s signature. Her afternoon was divided between five holdings. Each department then certified that the portion in its custody could no longer be spent by her. Nothing was destroyed; every minute survived the journey better than its owner. Across the yard, the stopped residents’ trailers have been boarded up with advertising for tomorrow’s programmes. The account still has an address for each minute. Elin no longer has an address.","The Hospital’s future holding paid to keep her interruption in place. It was never permission for another breath. Nurse Reed had once tried to spend such a balance for a patient and was charged with premature recovery. The Library received handling reserve; the collector received allowance; the threshold took its deposit. Every office can show an expense, and none can show her using a cup, opening a door, or telling her daughter goodnight. Pip asks who gets the balance if she dies. Vellum puts the sheet face down before answering.","You need the actual amounts. Pip moves five teaspoons into a row, one for each account. They came from different trailers after their owners stopped needing kitchens. When he notices you looking, he straightens them without explaining. Account for all ninety-three minutes. The office will not."],evidence:[{title:"Treasury reconciliation",text:"The departments retained ninety-three whole minutes in total. Elin’s portion plus the Library handling reserve equals forty. Library handling plus the threshold deposit equals thirty. The reconciliation records holdings, not proof that Elin was permitted to use them."},{title:"Collector's retained carbon",text:"Elin retained one minute more than twice the collector’s allowance. The ward held six minutes more than Elin. All five balances are whole and nonnegative. The carbon lists no sixth account into which a discrepancy can be placed."},{title:"Independent ward check",text:"Ward and Library together held forty-six minutes. This is an independent copying check on the same holdings. It contributes no additional minutes; adding it to the total would count retained time twice."}],resolution:["Twenty-three minutes remain Elin’s in every sense the department refuses to recognise. Seventy minutes fund the desks, collector, ward, and threshold that keep her from them. Vellum circles the twenty-three. The number is smaller than an afternoon and larger than the time Nettle needs to tell her mother what happened at school. “Now they can’t say it was used,” he says. Pip puts the teaspoons away. You have proved a theft; the stolen thing is still under lock, and the person it belongs to is still holding her breath."]},afternoon_sequence:{narrative:["The account agrees with itself. The records have been made to disagree with Elin. One notice says she had no future when the book was lent; another says the Hospital stopped her after an appeal. The public index rules that someone absent from it cannot have appealed in the first place. On the caravan wall, a poster explains that a regrettable outcome is never an unfortunate event if every department has acted correctly. The poster has been nailed over a hole.","Vellum kept the original records. Their dates were overwritten, but their events still depend on one another. A copied verse needed a borrowed book; an inspection needed something to inspect. Pip recognises his copy by the weak brown ring left by a cup. “I was there,” he says, and then goes silent. In this country, being there is the first fact an inspector can use against you. Vellum writes his name beside the statement. It means somebody has written down who was there with him.","Elin borrowed a book. Nettle pointed at an unfinished line. Pip copied it, and Vellum eventually objected. Arrange the seven actual events, using the surviving relationships instead of the altered dates. The collector arrived after the copy, without being invited by it. Pip needs to see that distinction on paper. "],evidence:[{title:"Pip's statement",text:"The book was borrowed before Pip copied the verse. The copy preceded the inspection, which preceded the notice. In the seven-event sequence, the notice stands exactly three positions after borrowing. These relations are what Pip remembers despite the overwritten dates."},{title:"Vellum's retained appeal",text:"Vellum filed the appeal immediately after the notice. The Hospital admitted Elin exactly two positions after the notice. The later rejection comments on the appeal; it is not an eighth event to insert between these seven."},{title:"Nurse Reed's annotation",text:"The Hospital admission preceded the public index’s erasure of Elin’s name. Every card represents one genuine event, occurring once. The imposed dates are disputed evidence and must not override these event relations."}],resolution:["The inspection came first; the reason came later. Elin had a future when she borrowed the book. The confiscation removed it, and the later records described the removal as a condition she had brought with her. Vellum writes CAUSE BEFORE CERTIFICATION in red pencil. Its point snaps halfway through the final word, leaving a gouge in the page. Pip studies the order until he can read it without looking away. It does not bring Elin back. It leaves less room for the office to say that her absence was her own fault."]},afternoon_route:{narrative:["The appeal is complete. The receiving office refuses it until four substations have handled the original in person. Ordinary delivery depends on the index, and the index has decided there is nobody to deliver for. Vellum opens a hatch into the Library’s old service level: cramped units joined by patched corridors, their previous owners’ wallpaper visible behind the shelves. A child’s height marks run up a door frame until the room became an accounts chamber. Nobody painted over them properly. Nobody mentions them either.","Pip wraps the original in his scarf. The copy witness, numerical audit, uncensored margin, and future cradle must be visited in that order. The lamps have twenty-four steps of appeal allowance. You must plan the entire journey through a place arranged to make the next refusal seem like a reasonable walking distance. At the far end, Nettle waits with a bookmark made from the cardboard inside a milk packet.","Vellum has frozen the passage charge while you study. It is the one discretionary exception he is allowed, and he has already been warned about making a habit of it. Only your submitted route will be counted. “Take the time you need to think,” he says, keeping his voice below the vent that carries sound upstairs. Build a route that fits the allowance without returning to any square. "],evidence:[{title:"Room coordinates",text:"Count rows downward from the top and columns rightward from the left, beginning at 1. Enter at row 1/column 1. The required stations are row 2/column 3, row 5/column 4, row 2/column 6, then row 6/column 6. The receiving desk is row 7/column 7."},{title:"Appeal passage rules",text:"Every move reaches one horizontally or vertically adjoining square. Closed rooms cannot be entered. No square may be used twice, including the starting square. A later station cannot be crossed before its turn. The submitted passage must fit the twenty-four-move allowance."}],resolution:["The desk accepts the appeal. Nettle asks whether she can take her mother home now. You tell her what the file can do: preserve Elin’s name and her claim. It cannot open the castle’s reservoir. Nettle folds the bookmark once along the old milk-carton seam and puts it in the book. She has kept her mother’s sleeping clothes dry inside a carrier bag. The clerk looks away from the bag and reaches for the next form. The accepted file lies between them, stamped with a date Elin has not been allowed to reach."]},afternoon_circuit:{narrative:["The public index is controlled by an eligibility board screwed into a wall of salvaged insulation. Five lamps represent basic claims; the surrounding lamps represent scrutiny, delay, repetition, and exception. Every category has been wired into its neighbours because separate circuits cost more. Elin’s file wandered through so many surrounding categories that the machine classified her as too obscured to recognise. ","The middle row must be lit: a clerk, a name, an address, a witness, a future. The other lamps must be dark. Vellum shows you the maintenance diagram and then the scorched mark where an earlier clerk tried to force a relay. “He thought it would be quicker.” A switch reverses its own lamp and the cells immediately above, below, left, and right. Order does not matter; two presses cancel. The cheap wiring is intact even when every label attached to it has gone wrong.","Pip sits beside Nettle on a folded coat. She has the willow drawing, but she is looking at the doorway through which her mother should have returned. Restore the exact middle-row pattern, and the corrected entry can reach all five counters. You will know the repair has worked when the desks can no longer use darkness as a reason to say that Elin was never there."],evidence:[{title:"Index maintenance diagram",text:"The index board has five rows and five columns. Recognition requires the five lamps of the middle row lit and every other lamp dark. A press reverses its own lamp and its immediate neighbours above, below, left, and right, where those neighbours exist."},{title:"Old technician's advice",text:"An odd number of touches reverses a lamp; an even number restores it. Choose presses for the top row, then press immediately beneath any difference remaining in the row above. Work downward. Once that upper row agrees with the target, the rows below can be handled without disturbing it."},{title:"Correction authority",text:"The target preview is the entire required recognition pattern. No rule demands that every switch be used or that the underlying records be destroyed. A corrected entry must retain the evidence of how the previous entry failed."}],resolution:["ELIN: PERSON. CLAIM: UNRESOLVED. FUTURE: WITHHELD, NOT ABSENT. The entry appears at every desk. Moss sends an apology addressed to Elin; Vellum puts it in the folder that will go beside her bed. The machine hums exactly as it did before. Nettle takes the willow drawing, then gives it back so you can find the living branch. “Bring this one back,” she says. Pip wraps the papers against the rain. You have repaired a record in a country whose ordinary machinery still makes people disappear."]},harvest_ledger:{narrative:["Sorrell’s trailer stands at the edge of the orchard on concrete blocks that have begun sinking into the ground. The roof is patched with packing foil, and a pear branch presses against the plastic window. The permit register names her Seasonal Output, Porcine. She has been holding up the branch since before dawn because its prop split and a replacement requires a request. Burrow brings an offcut from his office wall. She accepts it without thanking him. ","Five full crates left yesterday. Today the local allocation is exhausted. Each consignment charged its grower minutes to discourage excessive dependence on abundance. Sorrell asks whether a crate can eat a lunch break. He does not laugh. She has already paid for the fruit. Now she cannot afford the time to receive it.","Destination labels and charges were filed separately so a grower could inspect either record without making an unauthorised comparison. Your audit allows the comparison. Match all five consignments without inventing a sixth load or an exemption. Beyond the office, heaps of fallen fruit stain the gravel. A child is told to put down a pear because food from the ground has not passed allocation. The child puts it down. Sorrell watches until the inspector turns away."],evidence:[{title:"Dispatch accounting",text:"Every listed destination received exactly one crate and every charge appears once. The Hospital charge exceeds Compost by three. Storehouse exceeds Hospital by three, Casino exceeds Storehouse by three, and Castle exceeds Casino by three. The increments charge the grower, not the destination."},{title:"Grower's carbon copy",text:"Pear incurred the highest charge. Willow incurred exactly three minutes more than Millet. Apricot incurred less than Millet, and Plum less than Apricot. None of these comparisons describes how much food a crate held."},{title:"Burrow's correction",text:"The available charges are four, seven, ten, thirteen, and sixteen whole minutes. There was no additional shipment and no exemption. The destination labels record actual deliveries: the crate labelled Hospital did reach the Hospital. Those labels must not be treated as false to make the accounts fit."}],resolution:["The Hospital received apricots. Pears went to the castle, willow to the casino, millet to the locked storehouse, and plums to compost. Sorrell paid for every route, including the waste. Burrow changes LOCAL SHORTAGE to DISTRIBUTION UNEXPLAINED. He leaves the old heading visible underneath; an inspector will want to know why he corrected it. Sorrell sets the dispatch record beside her ration bowl. The figures are complete. There is still almost nothing in the bowl, and a whole orchard presses against the fence behind it."]},harvest_cipher:{narrative:["A dispatch ribbon is caught under the storehouse lock. Sorrell remembers its arrival after measurement and before applications opened. The inspector called it quality preservation, stood under the dry awning, and never looked inside a crate. Along the bottom of the door, brown liquid has begun soaking into the dust. ","Burrow remembers the packing convention: a keyword alphabet, then each word reversed because the stencil is read from the ribbon’s back. He learnt it when shipments still needed protection from roadside thieves. Now the code conceals an order from the people who loaded the shipment. He copies the decoding procedure onto a rejected heating application. Sorrell holds the ribbon against the wind while he writes. Its fibres have been softened by the leaking harvest.","The keyword, ABUNDANCE, remains over the permit window in letters repainted whenever the wall is patched. Ignore its repeated letters when building the substitution row. Decode the letters, then reverse each word separately. Sorrell listens to flies behind the door. “Frost doesn’t post an instruction,” she says. She wants the sentence that made this waste compulsory. Burrow has found a dry place for it in his pocket."],evidence:[{title:"Packing convention, first operation",text:"Build the keyed row by reading ABUNDANCE left to right, retaining only the first occurrence of each letter. After those letters, append all unused letters from ordinary A–Z in alphabetical order. The resulting row contains twenty-six distinct letters."},{title:"Packing convention, second operation",text:"Write ordinary A–Z directly above the keyed row. Locate each coded ribbon letter below and recover the ordinary letter above it. Then reverse each decoded word separately, keeping the words in their existing order. The stencil was read from the ribbon’s back."},{title:"Ribbon boundaries",text:"A slash separates words. No word or letter is missing, and no numeral is a substitute. Once the substitution and reversed stencilling are undone, the ribbon states the condition imposed on the harvest in ordinary language."}],resolution:["THE HARVEST IS HELD NOT LOST. The stamp belongs to the Museum’s Office of Appropriate Want. The produce is being withheld so visitors can encounter tasteful scarcity before entering an exhibition of abundance. Sorrell reads the instruction once and takes her hand off the warehouse wall. She had been listening for a fault in the ventilation. There is no fault to repair. Rotting was permitted by the order, hunger required by it. Burrow copies the issuing department’s name. A second trail of juice reaches the dust beneath the lock."]},harvest_balance:{narrative:["Burrow finds a release clause beneath the hold order. Seventy-two minutes of handling reserve can accompany the produce if five defined needs are met. The clause requires a complete allocation from the people least able to leave work and make one. It was written as a door with a desk pushed across it. Sorrell spreads the pages on the trailer’s steps. Her forearms remain sticky from the pear branch even after she wipes them on her trousers.","Workers need time to collect their own harvest. Patients need time to eat it. Travellers need time to carry it elsewhere. Seed keepers need an allowance for the next planting, and breakage must be covered without making whoever drops a basket pay from their personal clock. ","Patients receive six minutes more than workers; travellers receive three fewer. Seeds take half the workers’ amount and breakage a third. The total must be whole, nonnegative minutes. Burrow reads the fractional obligations twice because one decimal would void the release. Sorrell catches herself rubbing the empty space where her old wedding ring used to be. She sold it for one winter’s heating, and the fruit still grew the next spring. Find the amounts. These five needs should not require a proof, but they do require one here."],evidence:[{title:"Release clause",text:"Seventy-two minutes must cover all five allocations exactly. Patients receive six minutes more than orchard workers. Travellers receive three minutes fewer than those workers. Each field must contain a whole, nonnegative balance; neither hungry workers nor patients supply any extra."},{title:"Continuity obligations",text:"Seed keepers receive half the workers’ allocation. Breakage reserve receives one third of it. Both reserves are portions of the same seventy-two-minute release, not costs added after the release has been exhausted."},{title:"Independent check",text:"Patients plus travellers must equal twice the workers’ amount plus three. The relation follows from the first obligations and checks the copying. No allocation is taken from the time on a patient’s personal clock."}],resolution:["Eighteen for workers, twenty-four for patients, fifteen for travellers, nine for seed keepers, six for breakage. The figures fit without taking anything from a patient’s clock. Burrow signs and makes two copies on the reverse of unused refusal forms. Sorrell folds the travellers’ copy into the pocket with her ration card. The release will get some fruit out before it rots. It will not recover the meal breaks already paid, the hours spent pleading, or the food flattened under the wheels while they waited."]},harvest_sequence:{narrative:["The Museum objects before Burrow’s ink has dried. No valid applications existed when allocation closed. Its statement is accurate: the forms were printed after the fruit had been assigned. Workers stood beneath the promise of open access, then went home without food because they could not present documents the office had not yet produced. Sorrell remembers one man staying at the window until sunset, apologising for whatever he had failed to understand. ","She brings a seed packet, measurement slip, division ledger, permit proof, collection book, sealing photograph, and condemnation note. The contents expose a different order: branches counted before blossom, destinations settled before permission, unclaimed produce described as insufficient demand. Burrow recognises his signature on the permits. The condemnation note was already waiting in the packet. He lays the permits face up where Sorrell can see them.","Arrange the seven events from their actual relations. The appeal needs to show that failure to apply was built into the procedure. Sorrell smooths the empty seed packet with a flattened palm. Somebody had written her husband’s name on it when the soil was still borrowed between two occupied trailers. His time ran out before the first harvest. Your sequence can give the office less room to say the hungry people arrived too late."],evidence:[{title:"Gardener's event relations",text:"Measurement followed sowing immediately. Division came after measurement and before permit printing. In the seven-event account, collection stands exactly three positions after measurement. These relations survive beneath the office’s imposed dates."},{title:"Storehouse witness",text:"Permit printing preceded collection of applications. Sealing followed collection. Condemnation followed sealing. The seven cards account for every event in this sequence; there were no simultaneous events or extra events to place between them."},{title:"A date is not an event",text:"Each card describes something that happened once. Use the recorded relations to order them. The printed dates came from the office under audit and cannot take precedence over the events that its own witnesses describe."}],resolution:["Sowing, measurement, division, permit printing, collection, sealing, condemnation. The harvest had been promised elsewhere before its workers could ask for it. Burrow signs the chronology with his own name. Sorrell asks whether he will lose his post. He says he does not know. She folds the spare copy away with the seed packet. The late applications can no longer be used honestly as an explanation, but the office has never needed an honest explanation to make a refusal stick. At least this refusal now has a history somebody has kept."]},harvest_route:{narrative:["The exception needs four stations before it can open the storehouse. The roads were laid for carts going toward the castle. Getting food toward people requires a different path through gates added, moved, and welded shut over years of renovations. Outside, they are sagging wire, stacked bath panels, and an old trailer pushed across the gravel to become an inspection bay. None of these obstructions costs the office a minute. Every detour costs the person walking it.","Burrow marks the weighing bench, patient dispatch, seed table, and public witness post. You must visit them in that order. The last stands beside the Museum road, where someone outside the orchard will have to see the signed release. Sorrell checks the cart straps while you study. One is a length of curtain braided into rope. ","A pear stain has reached Pip’s drawing of the willow. Sorrell blots it with a sleeve and leaves the mark where it is. There are twenty-nine moves in the passage allowance, no revisits, and no early certification at a later station. Find the complete path before you submit it. Sorrell has spent years walking circuits from her trailer to somebody else’s fruit. She wants this journey to end with a door open. She does not let herself say that yet."],evidence:[{title:"The station order",text:"Rows count down from the top and columns across from the left, starting at 1. Begin at row 8/column 1. Visit row 3/column 3, row 3/column 5, row 6/column 6, then row 1/column 8. The public receiving post is row 1/column 7."},{title:"Cart-road regulations",text:"Move to horizontally or vertically adjoining squares only. Closed road squares cannot be crossed. No square may be revisited, and a later station must stay unentered until its turn. The release allowance covers at most twenty-nine moves on the submitted path."}],resolution:["The release reaches the public witness. A Museum courier has to receive it in view of people sitting along the fence with their empty bowls. Sorrell hands a pear to a traveller as soon as the receipt is marked. He starts eating before she takes her hand away. The courier notes the exchange without looking at his face. You now have the Museum’s order and a public record of its effect. Above the road, Supine’s reclining silhouette has been painted on new boards nailed across an older warning about subsidence."]},harvest_circuit:{narrative:["The storehouse recognises the release, then asks for confirmation from the allocation board. The board has been repaired with Library parts and bolted beside a disconnected drinks machine. Its exhibition setting lights the top while leaving the feeding ground dark. Burrow shows you the original tree diagram under a layer of nicotine-coloured varnish. Sorrell has spent her life keeping actual trees alive. She stands back from this one with her arms hanging loose. “Even the picture gets a better allowance than us,” she says.","Restore the precise leaf-and-stem target. The dry instructions occupy more space than the warning about the live terminals. Burrow puts his coat over the exposed side of the cabinet. He has no replacement fuses left.","While you plan, Sorrell moves the lunch-break sign to face the people outside the office. Burrow used to keep it facing inward as a reminder to postpone eating while applicants waited. Neither of them talks about the change. A rotten pear drops behind the fence and breaks open on gravel. Restore it so the existing release can be honoured. There is one usable door here. The country beyond it has not been repaired."],evidence:[{title:"The tree pattern",text:"Light row 1/column 3; row 2/columns 2, 3, and 4; all five lamps in row 3; and column 3 in rows 4 and 5. These are the crown, canopy, and stem in the retained diagram. Every other lamp must remain dark."},{title:"Shared wiring",text:"A switch reverses its own lamp and existing immediate neighbours above, below, left, and right. Edge switches therefore reach fewer lamps. Two uses of one switch cancel. Different presses may be reordered without changing their final result."},{title:"Technician's working method",text:"Test a press pattern across the first row. Then work down, pressing immediately beneath each lamp above that still differs from the target. If the chosen first-row pattern was suitable, the last row agrees after those differences have been chased downward."}],resolution:["The tree lights and the lock releases. Fruit leaves the storehouse as food. Sorrell opens the first crate slowly because she already knows some of what the delay has done. Burrow sets the Museum’s hold order in your hands. “Show her,” he says. He does not expect it to shame her; he hopes she will recognise her own name long enough to listen. Behind him, workers carry what is still edible past heaps they cannot save. You take the road toward the woman whose exhibition needed them to be hungry."]}},q=[{id:"missing_tomorrow",act:1,location:"library",title:"The case of the missing tomorrow",subtitle:"A mother is missing. The record says there was no mother.",premise:["The public clock hangs inside the original Library caravan. A slot beneath its face is labelled UNUSED AFTERNOONS. Nothing has come out in years. Rain has swollen the shelf below it until the books lean away from the wall. Vellum explains that returned time remains filed until its owner proves an appropriate intention to use it. A small mouse waits beside his desk. The bookmark in her hands was cut from food packaging and has a tassel longer than her arm.","Nettle’s mother, Elin, borrowed a book about tomorrow. The book returned; Elin was sent to the Hospital. At the allotment window, Nettle was told that there was no missing person because the index contained no person of that name. She asks whether the index knows who warmed her socks over the kettle, or who used to pull the wet blanket away from the trailer wall. Vellum takes off his spectacles. The answer he is required to give has stopped fitting in his mouth.","Pip offers to stay. His wings bear grey dust from the insulation he sleeps behind, and he handles the kettle carefully because its patched bottom leaks when tilted. He remembers Elin here. You will trace her afternoon through six parts of the Library: desks, binding, accounts, records, passages, and eligibility lamps. None will supply an easy rescue. Together they may establish that a person cannot be made never to have existed by editing the records of her life. The same counters will process your papers when this file is finished. Nettle has already learnt that being told to wait does not mean somebody is coming back."],conclusion:["Elin’s name returns. Nettle carries the corrected claim to the Hospital in a bag patched with transparent tape. A nurse will put it beside the unfinished book. The Library cannot release the castle’s reservoir or let Elin open her eyes. It can stop supplying the lie that there is nobody waiting for either thing. When Nettle reaches the door, she turns back to ask whether her mother can still be charged for a late return. Vellum crosses out the fee.","You take a copy of the willow footnote. An unspent moment still belongs to someone. Pip remembers the rhyme about feeding Lady Supine curly willow, and the path toward a living branch begins to feel less like an errand than a thin opportunity you cannot afford to lose. Behind you, Vellum puts Elin’s corrected folder back in its drawer. The drawer still sticks, the roof still leaks, and the public clock continues collecting unused afternoons. You now know one person whose afternoon it has kept."],challenges:[o("afternoon_ledger","Five desks, one absent person","Match each clerk to one seal and one defect. Every seal and every defect occurs once.",A,["Treat the numbered counters as positions. The address, reversed-date, and duplicate-kiss records occupy three consecutive counters.","The reversed date must be at counter 3: it needs an earlier witness/address pair and room for the White Eye two counters later.","Vellum: Green Door / Absent witness. Fen: Copper Leaf / Blank address. Silt: Black Bell / Reversed date. Rook: Blue Thread / Duplicate kiss. Moss: White Eye / Missing name."]),o("afternoon_cipher","Words behind the spine","Build the binding-order dictionary, decode each word:letter coordinate, and enter the three groups.",x,["Order the seven dictionary words by length, shortest first, then alphabetically among equal lengths. Number words and letters from 1.","The dictionary is FINITE, KETTLE, READER, UNDOOR, WILLOW, HOSPITAL, TOMORROW. A coordinate such as 4:3 means the third letter of UNDOOR.","Instruction: READ. Subject: THE WILLOW. Where to look: FOOTNOTE."]),o("afternoon_balance","The afternoon that balances","Recover all five integer account balances. None of these minutes was destroyed.",E,["Use Elin + Library and Library + Threshold to express Library and Threshold in terms of Elin.","Library = 40 − Elin, Threshold = Elin − 10, Ward = Elin + 6, Collector = (Elin − 1) ÷ 2. Substitute into the total.","Elin 23; Library 17; Collector 11; Ward 29; Threshold 13."]),o("afternoon_sequence","The crime before the offence","Arrange seven genuine records into the order the events occurred. The sources disagree about what that order means.",S,["The copy and inspection lie between borrowing and the notice. The appeal and freezing follow the notice.","The notice is three positions after borrowing. With the appeal next, freezing two positions after the notice, and erasure afterward, borrowing must be first.","Borrowing → Pip's copy → Inspection → Notice → Appeal → Hospital freezing → Name erasure."]),o("afternoon_route","A route for an unclaimed moment","Visit the four stations in their marked order, reach the receiving desk, and use at most 24 steps without revisiting a cell.",R,["Reserve the upper-right passage for the third station. Visiting it early cuts off your later return.","After station 1, go down and left to the lower-left sweep. Reach station 2 from its left, then turn upward toward station 3.","Using row,column from 1: (1,1),(1,2),(1,3),(2,3),(3,3),(3,2),(3,1),(4,1),(5,1),(5,2),(5,3),(5,4),(4,4),(3,4),(3,5),(3,6),(2,6),(2,7),(3,7),(4,7),(4,6),(5,6),(6,6),(6,7),(7,7)."]),o("afternoon_circuit","A name returned to a stopped body","Make the five lamps in the middle row glow, with every other lamp dark. Each press reverses its own lamp and its orthogonal neighbours.",C,["Presses commute and two presses cancel. Think in odd/even presses, not in how bright the board looks halfway through.","Try a pattern on the top row, then work downward: press directly below each unwanted lamp in the row above. Check whether the bottom row finishes correctly.","From Reset, press these row,column cells once each: (1,1),(1,4),(2,2),(2,4),(3,1),(3,4),(4,3),(5,1),(5,3),(5,5)."])]},{id:"abundance_audit",act:2,location:"fields",title:"An audit of excessive plenty",subtitle:"The orchard is full. The people beside it are hungry.",premise:["The Fields of Egregious Abundance rise behind chain-link fence and a line of derelict caravans used as permit offices. Timber props hold branches heavy with fruit. The paths are swept so inspectors will not slip on the fallen crop. Beyond the fence, workers eat lunches divided carefully enough that nobody has to mention how small they are. A fresh notice calls this contrast a healthy relationship between aspiration and restraint. Its nails pass through an older sign requesting clean drinking water.","Burrow has found a discrepancy he cannot stamp away. Five full crates departed yesterday; the local distribution ledger reports shortage today. Both pages add correctly. Sorrell, who grew and packed the produce, lives in the trailer nearest the orchard gate. She has spent more time maintaining its steps than the office has spent reviewing her claim. She asks where in these correct accounts food stopped belonging to the people who needed it. Burrow takes out his pen, but there is no field for the answer.","Your permit will let you cross the Fields. The audit follows what else has been made to cross: shipments, coded instructions, reserve minutes, deadlines, cart roads, and the lock’s wiring. Each board provides its full factual record. Reconstruct the records without assigning another hungry person the cost of an error. The trail leads toward the Museum, where Lady Supine displays scarcity as a deliberate composition. Here its subjects wait outside the fence in clothes that still smell of the crops they have been required to give away."],conclusion:["The release has witnesses. The Hospital receives fruit, the seed keepers retain their share, and workers carry salvageable produce along a road that had only taken it from them before. Burrow eats standing up beside his stamp. Sorrell removes one prop and lets an emptied branch rise. Under the storehouse awning, the ruined portion remains piled where the allocation delayed it. Nobody has time to bury it properly. For a few hours, the people outside the fence have food and the office has a record it cannot quietly replace.","Other storehouses remain locked. Your exception has an expiry, and the roofs beyond the fields will still need patching when the travellers’ fruit is gone. You carry the hold order, actual chronology, and shipment ledger toward the Museum. Supine enjoys hearing her compositions admired. This one has names, empty ration bowls, and a stain under the storehouse door. Pip’s willow drawing carries a smaller stain from a pear that finally reached somebody. He leaves it there when he packs the papers against the weather."],challenges:[o("harvest_ledger","The destinations of five full crates","Match each crate to its destination and the minutes charged to its grower. Each destination and each charge is used once.",I,["First use the three-minute chain to attach destinations to charges. Then order the crates using their inequalities.","Pear has 16. Plum < Apricot < Millet, while Willow is exactly 3 above Millet. Only Millet 10 leaves room for all those constraints.","Apricot: Hospital / 7. Pear: Castle / 16. Millet: Storehouse / 10. Willow: Casino / 13. Plum: Compost / 4."]),o("harvest_cipher","A harvest written backwards","Reconstruct the keyed alphabet, undo the substitutions, and reverse each decoded word.",N,["Write ABUNDANCE without repeated letters, then append the unused ordinary alphabet. Put that keyed row beneath A–Z.","The keyed row is ABUNDCEFGHIJKLMOPQRSTVWXYZ. Find a coded letter in that row and take the ordinary letter above it, then reverse each word.","THE HARVEST IS HELD NOT LOST."]),o("harvest_balance","Enough for five kinds of need","Allocate the released 72 minutes according to all five obligations, keeping every amount a whole number.",B,["Express all four other allocations in terms of the workers' amount. The two fractional reserves matter.","If workers receive w, the total is w + (w+6) + (w−3) + w/2 + w/3 = 72. Multiply through by 6.","Workers 18; Patients 24; Travellers 15; Seed keepers 9; Breakage reserve 6."]),o("harvest_sequence","An application submitted too late to exist","Put the seven harvest events in their actual order. Preserve the inconvenient distinction between a date and an event.",P,["Measuring follows sowing immediately. Division and permit printing must fit before collection.","Collection is three positions after measuring. Sowing therefore starts the sequence; sealing and condemnation occupy the two positions after collection.","Sowing → Measuring → Dividing → Printing permits → Collecting applications → Sealing → Condemning surplus."]),o("harvest_route","The orchard's other roads","Carry the release order through four stations in sequence and reach the Museum road in at most 29 steps, without repeating a cell.",O,["The first two stations are close, but taking their short shared corridor wastes the northern passage you need to keep available.","Go north from the start. After station 1, loop above it to station 2. Descend to station 3, then climb the eastern edge toward station 4.","Using row,column from 1: (8,1),(7,1),(6,1),(5,1),(4,1),(3,1),(3,2),(3,3),(2,3),(1,3),(1,4),(1,5),(2,5),(3,5),(4,5),(4,4),(4,3),(5,3),(6,3),(6,4),(6,5),(6,6),(5,6),(4,6),(4,7),(4,8),(3,8),(2,8),(1,8),(1,7)."]),o("harvest_circuit","A lock between hunger and rot","Restore the leaf-and-stem target pattern. Each press reverses its own lamp and its orthogonal neighbours.",H,["The target is a living tree, not a fully illuminated board. Compare each lamp with the target before choosing a press.","Choose top-row presses first, then chase differences downward. Press below each lamp that differs from the target in the row above.","From Reset, press these row,column cells once each: (1,2),(1,5),(2,1),(2,3),(3,2),(3,3),(4,1),(4,4),(5,2),(5,4)."])]}],s={min:3,typical:5,max:9},p=Array(25).fill(!1),f=(e,t=p)=>e.reduce((a,n)=>u(a,n,5),[...t]),L=[6,7,8,11,13,16,17,18].map(Number),_=[0,4,5,9,10,14,15,19,20,24].map(Number),g=p.map((e,t)=>L.includes(t)),b=p.map((e,t)=>_.includes(t)),D=[{id:"portrait_testimony",act:3,location:"museum",title:"The people beneath the portrait",subtitle:"Five lives were painted over. Their labour remains beneath the gold.",premise:["The Museum was once a roadside assembly hall. Successive renovations added false marble, boarded over windows, and built annexes from caravans whose owners had run out of time. The newest portrait hides a cupboard called the Department of Things Not In the Pictures. Inside are purchase slips for five studies from the Shanty Hours. They were enlarged and absorbed into THE EXCEPTION, THE GIFT, and THE REST. Their makers’ labels were removed. The catalogue calls the loss an improvement in universality; the cupboard smells of old paste and damp coats.","Your companions stand close enough to keep their voices from carrying into the hall. Brindle carves wooden birds when his hands have anything left after work. Ada repairs clocks with parts she cannot afford to replace. Pip finishes poems other people have no time to finish. A folded notice says ORDINARY SUBJECTS MUST NOT DISTRACT FROM EXTRAORDINARY AUTHORSHIP. Brindle recognises a shaving beneath one frame. Ada notices counters charging visitors for the length of their attention. An Aristobat hangs outside, listening to prepared praise. The Curator has saved enough scraps to establish whose days were used, what the Lady removed, and what it cost the people who gave her something beautiful. He has not saved enough to make telling you safe. He opens the cupboard anyway."],challenges:[{id:"portrait_sources",title:"Five frames, five missing people",narrative:["Five studies hang in numbered frames. A sleeping neighbour became a white chair. A child’s shoes became empty footwear; a wash basin became divine sand; a carved bird became a wingless herald; a bread cloth became the Lady’s spotless pillow. The dark lines beneath the new paint still describe what had been there. ","The Curator saved the purchase slips in a box for replacement bulbs. Five people supplied five studies, each with one subject and one maker. “Please keep those things separate,” he says. The old paint gives a glimpse of rooms like those outside: a table pushed against a leaking wall, washing beneath a single dead bulb, someone sleeping with their coat on. The approved pictures have no need of a roof or a night shift. Each ordinary room has become an occasion for a woman who never had to live in it.","Brindle sits beneath the fourth frame with his hands closed around an empty place in his lap. He used to carve birds during the hours nobody paid him for; you have never seen him carry one. Pip reads the slips softly so the Aristobat outside cannot hear the names. Match maker and subject to the five frames. None of the restoration will give the makers their spent afternoons back. It can at least stop their work from continuing under somebody else’s face without even their names attached."],task:"Assign one ordinary subject and one original maker to each frame. Use every option exactly once in each column.",evidence:[{title:"The registrar’s language",text:"The register uses left of for any position farther left, and beside for an immediately adjoining frame. All five frames contain one maker and one subject, with every listed maker and subject appearing exactly once. The labels were detached; the purchase relations were not."},{title:"Purchase slips, first bundle",text:"The sleeping neighbour’s study hung left of Fenn’s frame. Wooden bird and bread cloth occupied adjoining frames. Sella’s frame hung left of Orris’s. Wash basin hung left of Brindle’s frame. These refer to frame positions, not the subjects’ or makers’ relative worth."},{title:"Purchase slips, second bundle",text:"Child’s shoes adjoined Marta’s frame. Exactly one intervening frame separated child’s shoes from wooden bird. Brindle hung left of Fenn. Wash basin was not at either end. Orris occupied the frame immediately left of Marta. Nothing on the final captions overrides the purchase slips."}],board:{kind:"ledger",rows:[1,2,3,4,5].map(e=>({id:`frame${e}`,title:`Frame ${e}`})),columns:[{id:"subject",title:"Ordinary subject",options:["Sleeping neighbor","Child’s shoes","Wash basin","Wooden bird","Bread cloth"]},{id:"maker",title:"Original maker",options:["Sella","Orris","Marta","Brindle","Fenn"]}],solution:{"frame1.subject":"Sleeping neighbor","frame1.maker":"Sella","frame2.subject":"Child’s shoes","frame2.maker":"Orris","frame3.subject":"Wash basin","frame3.maker":"Marta","frame4.subject":"Wooden bird","frame4.maker":"Brindle","frame5.subject":"Bread cloth","frame5.maker":"Fenn"}},hints:["Combine “Orris immediately left of Marta” with the wash basin’s position and the two-frame separation between shoes and bird.","The basin belongs in the middle. The bird and bread cloth must occupy the last two frames, with Brindle before Fenn.","Frames 1–5: sleeping neighbor / Sella; child’s shoes / Orris; wash basin / Marta; wooden bird / Brindle; bread cloth / Fenn."],resolution:["“The fourth was mine,” Brindle says. Supine paid enough time to patch his roof through one wet season. He had thought the bird would outlast the patch. Sella drew a neighbour sleeping after work; Orris drew outgrown shoes; Marta watched a basin; Fenn covered bread for someone arriving late. The Curator writes their names in pencil because official ink is locked upstairs. Brindle keeps staring at the shape beneath the gilding. He does not ask for it back. Marta’s slip carries another message, written in the old protective cipher."],minutes:s},{id:"portrait_washday",title:"What the water was for",narrative:["Marta’s basin study sits beneath glass too clean for the room it depicts. The approved hand is human and impossibly pale; the receiving hand is furred. Its caption thanks the Lady for water. Under angled light, an older pair of furred hands becomes visible, holding the same torn sleeve above a tin bowl. Marta’s caravan had no running supply. Washing meant carrying water past the permit window and warming it on a stove that marked every kettle with soot. Neither hand was giving a gift. Both were working.","Supine visited on an early telescreen mounted to a stand with one crooked wheel. Marta put it beside the basin because there was no other clear surface. She spoke while scrubbing, forgot the formal address, and talked about her sister. Supine requested the study the following morning. It was paid for, then revised until the ordinary conversation resembled gratitude. ","The explanation survived in a box marked UNSUITABLE ARTISTIC MOTIVES. It was indexed into a verse, so a casual inspection would encounter harmless lines instead of a person’s account of an afternoon. Use the written indexing rule; a shift in reading direction can quietly turn a correct word into another mistake. Pip places a saucer beneath the basin’s drip in the drawing, then realises what he is doing and removes it. "],task:"Decode the two indexed messages. Enter the maker’s name and the single word naming the original purpose.",evidence:[{title:"The indexing rule",text:"For row : word : letter, number all six rows from the top. On odd rows, count words leftward to rightward; on even rows, count them from the right. Within the selected word, always count letters from the left. Ignore punctuation but retain every word. Only word direction reverses."},{title:"The six rows",text:`1. Mended sleeves sheltered an ordinary afternoon
2. Patient hands borrowed colours from daylight
3. Beneath official gold somebody kept company
4. Brindle watched small shavings become birds
5. Marta carried tea through tired doorways
6. No crown can remember another person`},{title:"A note from the Curator",text:"The first message identifies the maker named on the purchase slips. The second is one thirteen-letter word describing why someone remained beside another person for an afternoon. It names no purchase, debt, or other transaction."}],board:{kind:"cipher",inscription:`MAKER: 3:6:3 / 4:4:3 / 6:3:1 / 5:5:1 / 5:1:2
PURPOSE: 4:5:4 / 3:4:2 / 6:3:5 / 2:6:1 / 5:1:2 / 2:5:3 / 4:6:3 / 3:4:2 / 6:6:1 / 4:4:1 / 2:5:1 / 1:5:4 / 6:1:1`,fields:[{id:"maker",label:"Maker’s name"},{id:"purpose",label:"Original purpose"}],solution:{maker:"Marta",purpose:"companionship"}},hints:["The word direction reverses on rows 2, 4, and 6. The letter direction never reverses.","3:6:3 selects the third letter of “company”: M. The purpose begins C O M P.","The maker is MARTA. The purpose is COMPANIONSHIP."],resolution:["MARTA. COMPANIONSHIP. Her sister had gone to the Hospital. Marta washed the sleeve because it was one of the few things left in her trailer that still carried the sister’s shape. Supine stayed on the little screen while she worked. Later, the Lady’s hand replaced theirs, and the cuff’s hole disappeared. Pip reads the recovered word without attempting a rhyme. You keep the explanation with the study. Whatever tenderness Supine once saw here, she used her revisions to leave its grieving owner outside the picture."],minutes:s},{id:"portrait_restoration",title:"An ordinary restoration grant",narrative:["On the studies’ backs, a second account records forty-two minutes of preservation grant. Ink, wood, thread, tea, and light were its named purposes. The receipts describe work the grand labels have forgotten: returning names to a register, propping a chair, closing a cuff, keeping a visitor at the table, lighting the room after paid work. The Museum stored the grant in a display counter instead. A smiling Supine coupon rotates behind glass. ","The Curator cannot release the counter without the exact five allocations. A mismatch summons the Aristobats and converts restoration into debt. Ada opens the casing without disturbing the seal, using a strip of metal she carries in her shoe. She waits for you to recover the account before touching its circuit. ","Brindle recognises the chair’s split support in the wood receipt. Pip recognises the tea allowance, though he does not say who supplied it when the grant remained unspent. Behind the counter, the Lady’s face turns past an old stain that nobody has been authorised to clean. These minutes will support small repairs already deferred beyond reason. The arithmetic cannot make the original rooms dry or undo the loss of the people who used them. It can release the value trapped in this display, if every receipt agrees. Ada keeps her hand beside the exposed wire."],task:"Recover the five whole-minute allocations, satisfying all five conditions together.",evidence:[{title:"The sealed grant",text:"The original grant contained forty-two minutes across these five purposes. None was lost or carried into another period. There is no sixth, unlisted purpose to absorb an excess. The display retained the same total it was supposed to release."},{title:"Brindle’s purchase record",text:"Wood received four minutes more than ink. Ink and thread together received fifteen. These receipts name actual allocations; the size of the frame is not an additional charge."},{title:"The table receipts",text:"Thread plus tea equals fourteen minutes. Tea plus light equals sixteen. Both relations refer to the same five-purpose grant and must hold together with the sealed total."}],board:{kind:"balance",fields:[{id:"ink",label:"Ink",min:0,max:42,suffix:"minutes"},{id:"wood",label:"Wood",min:0,max:42,suffix:"minutes"},{id:"thread",label:"Thread",min:0,max:42,suffix:"minutes"},{id:"tea",label:"Tea",min:0,max:42,suffix:"minutes"},{id:"light",label:"Light",min:0,max:42,suffix:"minutes"}],equations:["Ink + wood + thread + tea + light = 42","Wood = ink + 4","Thread + tea = 14","Ink + thread = 15","Tea + light = 16"],solution:{ink:"7",wood:"11",thread:"8",tea:"6",light:"10"}},hints:["Express wood and thread in terms of ink. Then use thread + tea to express tea, and tea + light to express light.","If ink is x, the other allocations are x + 4, 15 − x, x − 1, and 17 − x. Substitute all five into the total.","Ink 7; wood 11; thread 8; tea 6; light 10. Their sum is 42."],resolution:["Ink seven, wood eleven, thread eight, tea six, light ten. Ada disconnects the display and routes its minutes to the original accounts. The revolving face stops sideways against the glass. The Curator watches it long enough to realise no announcement is coming. He stamps the receipts and puts them under a board so they will stay flat. Among them are the dates of Supine’s revisions, some before the watchers arrived and some after. "],minutes:s},{id:"portrait_layers",title:"The order of disappearance",narrative:["Seven cards describe the layers that changed Marta’s washday into THE GIFT. The first lines were drawn on cheap board bent from steam. Beneath those improvements the torn sleeve disappeared. The second chair disappeared too. At the end, one magnificent hand gives and one lesser creature receives. The difficulty of carrying water, the sister’s absence, and the reason to remain beside the bowl have nowhere left to sit.","Ada follows the outline of the erased chair. “It took several attempts,” she says. The Curator explains that the final watching eye was ordered by the Aristobats; Supine signed the revision as her own decision. The earlier erasures also belonged to her. In the hall, visitors repeat the supplied interpretation before they have reached the picture. A microphone checks their words.","Pip asks about the preservation tracing. It should record the painting before the first erasure, if you can establish when it was made. The restorer’s cards have been filed according to the size of each commendation. Their relations remain legible beneath the praise: chair, cup, sleeve, eye, varnish. Arrange all seven stages in actual order. If its departure came early enough, it may be the only witness left to the room as Supine first saw it. "],task:"Put the seven alterations in chronological order, earliest first. All clues describe this same single painting.",evidence:[{title:"Drying records",text:"Exactly three alterations lie between the tracing and addition of the official eye. Divine varnish followed the eye immediately. No other event can be inserted between eye and varnish to make the chronology appear more gradual."},{title:"Layer boundaries",text:"The cup was replaced before the torn sleeve was covered. The second chair was erased after the tracing and before the cup replacement. These are layer boundaries observed in this one image, not dates borrowed from another painting."},{title:"The restorer’s certificate",text:"The ordinary original preceded erasure of the second chair. Taking the preservation tracing was not the first of the seven events. Each card belongs once in the same sequence."}],board:{kind:"sequence",cards:[{id:"eye",title:"Add the official eye",description:"The room begins watching whoever looks into it."},{id:"original",title:"Draw the ordinary original",description:"Two hands, one basin, a shared afternoon."},{id:"varnish",title:"Apply divine varnish",description:"Every imperfection is declared intentional."},{id:"cup",title:"Replace the cup with an hourglass",description:"Tea becomes an allocation of scarce time."},{id:"trace",title:"Take the preservation tracing",description:"A copy leaves the studio for the frame maker."},{id:"sleeve",title:"Paint over the torn sleeve",description:"The thing being mended disappears."},{id:"chair",title:"Erase the second chair",description:"Company becomes a one-sided audience."}],solution:["original","trace","chair","cup","sleeve","eye","varnish"]},hints:["The eye must have varnish immediately after it. Counting the three intervening events restricts where the tracing can stand.","The tracing cannot be first, so it is second and the eye is sixth. Fit chair, cup, and sleeve into the three spaces between them.","Original → tracing → second chair erased → cup replaced → sleeve covered → official eye added → divine varnish."],resolution:["The tracing left before the chair was erased. Brindle’s uncle made the frame, kept the clean reference, and died without knowing it would become evidence. The eye was added after the shared room had already been emptied. Observation then rewarded what Supine had chosen to remove. You copy the dates while the Curator watches the hall. The archive still holds the tracing. Somewhere under this building’s patched floor is a sheet of paper that reached a workman before the Lady could turn every other person in it into an audience."],minutes:s},{id:"portrait_archive_walk",title:"A corridor the cameras cannot finish",narrative:["The archive occupies a run of eight-by-eight service bays under the Museum. Closed restoration units form black squares on the plan; the remaining passages are pale. In the actual corridor, hardboard hides disused doors and water creeps beneath each new partition. Cameras compare a visitor’s route with the previous visitor’s. Repeating a square is treated as returning to admire the Lady. An escort takes you upstairs, enters the admiration against your account, and prevents the return. ","Ada has arranged four visits that supply a legitimate route to the tracing: original negative, frame loan, grant release, raw caption. Each provides authority for the next. The final cabinet rejects paperwork collected in another order, even if its contents are identical. The Curator marks the sealed bays where old frames lean against the damp. ","Brindle checks a barrier and finds he could lift it. The Curator touches his sleeve once and then removes his hand. The camera records equipment damage even when it does not record a face. Pip waits at the first junction with the papers inside his coat. There is room for forty-five moves before the archive closes for its automatic break. Keep each square unique and every stop in order. Nobody smiles at the peculiar rules. All of them have lost an afternoon to a rule smaller than this."],task:"Plan a route through all four marked archive stops in order. Move horizontally or vertically, never revisit a square, and use at most 45 steps.",evidence:[{title:"Archive coordinates",text:"Rows run downward from the top and columns rightward from the left. Start at row 1/column 1. The tracing cabinet is row 5/column 8. Both belong to the mapped archive; no passage outside it may be substituted."},{title:"Document order",text:"Collect original negative at row 2/column 7, then frame loan at row 8/column 2, grant release at row 6/column 7, and raw caption at row 5/column 7. Each authorises the next, so the visits must occur in this order."},{title:"Inspection policy",text:"A closed bay cannot be entered. Entering a marked station before its turn invalidates the accumulated papers. Visiting any square twice triggers an escort out of the archive. The valid route must use only orthogonal moves and fit the forty-five-step allowance."}],board:{kind:"route",width:8,height:8,blocked:[17,18,19,22,25,26,29,30,49,50,52,53],start:0,end:39,waypoints:[14,57,46,38],maxSteps:45,solution:[0,1,2,3,4,5,6,7,15,14,13,12,11,10,9,8,16,24,32,40,48,56,57,58,59,60,61,62,63,55,47,46,45,44,43,42,41,33,34,35,36,37,38,39]},hints:["Do not descend into the middle before collecting the negative. Keep a separate way back up to the caption.","One safe route uses the top edge, the left edge, and the bottom edge, then folds inward through rows 6 and 5.","From the start: right 7, down 1, left 7, down 6, right 7, up 2, left 6, up 1, right 6. This visits all stops in order in 43 steps."],resolution:["The tracing cabinet opens. Marta holds the sleeve beside a tiny telescreen; Supine has drawn her own screen badly and the wet cuff with painful care. Brindle bends close to the paper and says nothing. On the reverse is a small bed beneath an open window, with a second chair left plain. There is no watching eye. The tracing has stayed here through roof repairs and catalogue revisions, curled at one edge where the damp entered its frame. To see the faint drawing clearly, you still need the original arrangement of archive lamps."],minutes:s},{id:"portrait_window",title:"A window instead of an eye",narrative:["The lamp panel originally illuminated the tracing from several directions. Later, a cable tied it to the inspection system. Now light thrown onto the picture returns as glare, placing the viewer’s reflection over the faint bed and window. The preserved diagram shows eight lights surrounding a dark centre. Its maker wanted the paper visible without turning the person looking into another obstruction. That maker’s label has been peeled off. Only two staples and a little clean rectangle remain beside the live terminal.","Ada tests a disconnected switch. Each press reverses its own lamp and immediate orthogonal neighbours; diagonal lamps stay unchanged. She tapes a loose contact back into place with a strip from her clock case, then asks you to plan the target before reconnecting it. Brindle holds a cardboard shade over the panel. In the hall, the Aristobat hears a relay click but cannot see which cabinet it belongs to. ","Pip has found a line on the reverse: FOR A ROOM IN WHICH ONE MAY STOP. He leaves it as a statement instead of making it rhyme. Supine once drew an unremarkable bed, a window, and somewhere another person might sit. It gives you one honest detail to mention when a dishonest compliment would be safer. Restore the exact ring of eight lamps, with the centre and border dark. "],task:"Match the target lamp pattern. Each switch toggles its lamp and its four orthogonal neighbors. Use the target preview as the restored window.",evidence:[{title:"Linked switches",text:"Each press reverses its own cell and immediate orthogonal neighbours. Diagonal lamps never change, and no lamp exists beyond a board edge. Two identical presses cancel; the order of different presses makes no difference to the final lamps."},{title:"The original lighting design",text:"In the three-by-three square at the board’s centre, light the eight lamps surrounding the centre cell. Leave that centre and the entire outer border dark. The target preview records the complete arrangement needed to remove the inspection glare."},{title:"Ada’s method",text:"Correct differences in an upper row by pressing immediately below them. The second row can change the first without affecting an earlier row. Note each press; a promising pattern can then be repeated or corrected instead of lost when the glare returns."}],board:{kind:"circuit",size:5,initial:f([0,2,4,6,9,11,15,18,21,24],g),target:g,solution:[0,2,4,6,9,11,15,18,21,24]},hints:["Work with differences between the current board and the target. ","Starting from the original board, presses at R1C1, R1C3, and R1C5 are part of one complete solution. The remaining presses occupy seven cells across the lower four rows.","Reset, then press R1C1, R1C3, R1C5, R2C2, R2C5, R3C2, R4C1, R4C4, R5C2, R5C5 once each, in any order."],resolution:["The bed and open window appear under the restored light. There is space for somebody beside them, and no promise that anyone will come. The Curator sets the five corrected labels next to the tracing. Brindle folds his purchase slip until it fits his pocket. Pip copies the line exactly. Ada disconnects the counter from this panel, leaving one picture that will not charge anyone for looking. Your compliment now has a subject: an ordinary room the Lady once drew before she removed the people whose lives made it ordinary."],minutes:s}],conclusion:["Five makers’ names return to the record. The monumental pictures remain where they were, lit above a gallery whose ordinary subjects would struggle to afford admission. The Curator stores the tracing flat and keeps the corrected labels close to it. He does not replace the rule against independent interpretation. He loosens one corner so it can be lifted to reveal the record beneath. It is the amount of defiance he can manage while an Aristobat sleeps outside the door.","On Channel 9, Supine adjusts her chin against a stain-free pillow. You can speak honestly about the wet cuff, the small bed, and the room where another person might have stayed. Your friends wait with you. Their own rooms still need mending, and their clocks still charge the time spent here. If she offers a wish, you will ask for time. Whatever beauty she once recorded, the people who supplied it have not been allowed enough time to live with one another."]},{id:"continuity_patient",act:4,location:"hospital",title:"The patient without a yesterday",subtitle:"The form has misplaced yesterday and offered a living brain as spare tissue.",premise:["The Hospital is a row of trailers joined by covered walkways. Some windows are replaced with bags; others are painted white so patients do not have to watch the allotment clock outside. Nurse Reed leads you to an otter’s bed labelled PATIENT PENDING PREVIOUS EXISTENCE. She arrived after the office misplaced yesterday. Her body is here, her account is closed, and the form offers her brain as unwritten stock. Reed has crossed out the classification so hard that the paper has split. The patient holds a folded cloth between fingers that have not finished closing.","Anima has heard your plan to exchange Ada’s brain with the living brain inside Supine’s head. The Lady’s large head opening will admit the shuttle; Ada’s skull will have to be opened by hand. Before he approves any preparation, he makes you attend to this patient. “We do not fill your spare jar with someone the office failed to record.” Ada takes the place beside the bed, Pip brings a pencil, and Brindle stands where he can keep the patched curtain from blowing against the patient’s face. You must establish who is here and what she wants. A date can disappear from a file without removing a life from the organ the doctor has been asked to use."],challenges:[{id:"patient_window_words",title:"A memory the chart cannot own",narrative:["The otter watches rain crawl down a plastic pane. Reed asks what she wants, and her mouth moves without enough allotted time to produce a sound. She lifts the folded cloth a fraction toward the sill. The cuff is washed and mended; it has the same shape as the sleeve in Marta’s tracing. The fabric was easier to keep registered than the body holding it.","Pip finds a stitched poem inside the lining. Families use such codes to send memories into the still ward. An inspector may read the poem, but unpicking its stitches spends thread and requires approval. Names can survive where approvals do not reach. The code should identify the wearer and a remembered place. Brindle moves a chair that was blocking the rain, then stands because the floor is too narrow for both.","Anima asks you to wait. A recovered name is no permission to cut open a head. Ada asks the patient whether the seam may be read. Her eyes move from the stitches to you and back. Reed waits for the same movement twice, then records assent to reading only. The bed is already marked as a possible source of unwritten tissue. A missing date has made a person convenient to a procedure. You need to find who is here before an office decides there is nobody to lose."],task:"Decode the lining’s two messages: the wearer’s name and the single word naming a remembered place.",evidence:[{title:"The family’s rule",text:"Read a triple as row : word : letter. Count rows from the top and words from the left, beginning at 1. In the selected word, count letters from the RIGHT edge, also beginning at 1. Ignore punctuation. Use this same rule on all six rows; a missing date does not alter the code."},{title:"The stitched poem",text:`1. Rain waited outside while kettles hummed
2. Someone placed flowers beside the warm glass
3. My mother opened windows before anybody woke
4. Remember how small birds arrived without appointments
5. We counted silver drops across the sill
6. Tomorrow will come when someone keeps company`},{title:"Reed’s reminder",text:"The remembered place is one uninterrupted word containing ten letters. The recovered name lets you address the person who is here. Neither message authorises a procedure or requires the wearer to return to a former life."}],board:{kind:"cipher",inscription:`WEARER: 4:7:5 / 6:7:6 / 4:1:8 / 3:2:1 / 5:5:3 / 5:1:2
PLACE: 5:1:2 / 4:7:8 / 3:3:3 / 1:2:1 / 5:5:3 / 5:1:2 / 5:7:4 / 4:7:8 / 4:3:2 / 4:3:1`,fields:[{id:"wearer",label:"Wearer’s name"},{id:"place",label:"Remembered place"}],solution:{wearer:"Morrow",place:"windowsill"}},hints:["Count letters backward inside each selected word, but keep the recovered letters in the message’s printed order.","4:7:5 selects the fifth letter from the right of “appointments”: M. The place begins W I N D.","The wearer is MORROW. The remembered place is WINDOWSILL."],resolution:["MORROW. WINDOWSILL. Reed says the name and the patient’s fingers close around the cuff. Marta’s sister is still here. She wants the flowers beside the plastic pane, close enough to see the rain move behind them. Anima records the request without replacing it with a diagnosis. The ward form has space for organ availability but none for flowers. Reed writes the request over that space. A small, present wish has interrupted the paperwork that was preparing to classify her brain as unused material."],minutes:s},{id:"patient_five_continuities",title:"The ward of misplaced traces",narrative:["Five charts were mixed when the Hospital installed a sorting machine salvaged from the ration office. It alphabetised patients by the last word they spoke, then discarded those words as medically irrelevant. Five envelopes ended at five wrong beds. Reed unplugged it and kept the envelopes in her uniform. She has worn the same uniform through enough shifts that a pocket has torn around one chart’s folded corner.","Each envelope holds an admission name and a continuity trace: song, smell, habit, promise, or spoken name. None is a test of whether a body deserves a bed. You can reconstruct the correspondence without assuming species, appearance, or a silent mouth determines what somebody remembers. Morrow is watching the newly moved flowers. Their water is in a chipped specimen jar with a previous label still stuck to it.","Brindle once knew a porter who could name every meal of his childhood by its smell and could no longer name the person cooking beside him. Pip remembers songs he does not have breath to sing. Ada reads the promise field and folds that envelope inward, making sure its private contents remain private. Match the five patients and traces to the numbered beds. The charts need to stop wandering before another mistaken envelope becomes authority to treat a living brain as though nothing has ever happened inside it."],task:"Assign a patient and one continuity trace to every bed. Beds are numbered left to right; use each patient and trace once.",evidence:[{title:"How to read the ward notes",text:"Beside means the immediately adjoining bed. Left of means anywhere farther left, without requiring adjacency. The notes describe the original bed order before the sorter displaced the envelopes."},{title:"Reed’s first pocket",text:"Tern and Sable occupied adjoining beds, with Sable to Tern’s left. Song lay left of Habit. Exactly one bed separated Smell and Habit. Sable’s trace was Habit. Each relation applies to the same five beds."},{title:"Reed’s second pocket",text:"Name belonged to neither end bed. Song adjoined Habit, and Elsi adjoined the bed with Habit. Promise lay left of Morrow. Every patient and every continuity trace is used once; none may be discarded because a chart went missing."}],board:{kind:"ledger",rows:[1,2,3,4,5].map(e=>({id:`bed${e}`,title:`Bed ${e}`})),columns:[{id:"patient",title:"Patient",options:["Tern","Elsi","Morrow","Hollis","Sable"]},{id:"trace",title:"Continuity trace",options:["Song","Smell","Habit","Promise","Name"]}],solution:{"bed1.patient":"Hollis","bed1.trace":"Promise","bed2.patient":"Elsi","bed2.trace":"Song","bed3.patient":"Sable","bed3.trace":"Habit","bed4.patient":"Tern","bed4.trace":"Name","bed5.patient":"Morrow","bed5.trace":"Smell"}},hints:["Sable and Tern must be neighbors in that order. The Name trace and the two-bed separation of Habit and Smell narrow their positions.","Habit belongs in bed 3. Song is in bed 2, Name in bed 4, and Smell in bed 5. Use the remaining patient clues.","Beds 1–5: Hollis / Promise; Elsi / Song; Sable / Habit; Tern / Name; Morrow / Smell."],resolution:["Morrow’s trace is the smell of rain on warm brick. Reed opens the pane a little, though the brick outside has not been warm for days. Hollis’s promise concerns a child’s birthday; Elsi’s song stops before its last line. Each envelope returns to its proper bed. Anima changes INVALID PERSON to INVALID CORRESPONDENCE on the machine’s labels. The charts keep five people’s names beside five bodies whose time the Hospital has been required to hold still."],minutes:s},{id:"patient_reserve",title:"Forty-four minutes of care",narrative:["Forty-four minutes remain in the still ward’s reserve. They were donated by people who left; some left on their feet and some left with coupons their relatives could no longer redeem. Reed keeps them in a biscuit tin because the treasury charges storage. Rust has reached one corner, and she lines it with a folded discharge form. Morrow could receive eight minutes of waking only if the complete allocation supports it: care, listening, warmth, writing, and observation. ","The reserve serves the ward; no patient’s personal clock will pay for the others. Reed has not promised that waking Morrow will end the shortage. Blank administrative charges have swallowed earlier donations before the person they were intended for could spend them. Anima lays out the supporting totals and relations. His hands look steady over the paper, less steady when he takes them away from it.","Ada asks why observation exceeds listening. The allowance includes the time after the waking ends, when everybody who watched it happen would prefer to go home. Brindle shifts his feet beside the bed. He has stayed through that part before. Pip draws five empty containers, then crosses out the drawing because it looks like another system sorting things. Recover the allocations before opening the tin. Morrow’s consent will still be needed when the interval is offered. "],task:"Recover five whole-minute allocations from the reserve. Enter nonnegative integers satisfying the total and all four receipt relations.",evidence:[{title:"The biscuit-tin total",text:"The tin contains exactly forty-four minutes for these five allocations. Care names the waking interval itself; the other four allocations pay for the work that supports it. Each purpose appears once in the total. There is no separate supply beyond the tin."},{title:"Reed’s receipts",text:"Care plus listening equals thirteen minutes. Listening, warmth, and writing together equal twenty-three. Care plus writing equals fifteen. All three receipts refer to the same ward reserve and must agree."},{title:"The doctor’s last note",text:"Observation receives exactly two minutes more than warmth. The allowance includes remaining after the waking interval, even when the event everyone came to see has ended."}],board:{kind:"balance",fields:[{id:"care",label:"Care",min:0,max:44,suffix:"minutes"},{id:"listening",label:"Listening",min:0,max:44,suffix:"minutes"},{id:"warmth",label:"Warmth",min:0,max:44,suffix:"minutes"},{id:"writing",label:"Writing",min:0,max:44,suffix:"minutes"},{id:"observation",label:"Observation",min:0,max:44,suffix:"minutes"}],equations:["Care + listening + warmth + writing + observation = 44","Care + listening = 13","Listening + warmth + writing = 23","Observation = warmth + 2","Care + writing = 15"],solution:{care:"8",listening:"5",warmth:"11",writing:"7",observation:"13"}},hints:["Subtract the three-purpose receipt from the total. The difference contains only care and observation.","Care + observation = 21. Therefore care + warmth = 19. Replace listening with 13 − care and writing with 15 − care in their shared receipt.","Care 8; listening 5; warmth 11; writing 7; observation 13. Their sum is 44."],resolution:["Care eight, listening five, warmth eleven, writing seven, observation thirteen. Reed puts the coupons in five envelopes and leaves them unredeemed until Morrow agrees. The biscuit tin is nearly empty enough to close flat. Anima leaves the account where anyone returning to the ward can read it. Ada studies observation’s thirteen minutes. Your proposed exchange will leave a friend in a body that Supine’s brain has occupied. Getting her back will require care after the grand room and its Switch are behind you. Nobody can afford to leave that work unnamed."],minutes:s},{id:"patient_transfer_order",title:"A mind travels with its name",narrative:["Morrow agrees. Reed redeems the first care coupon; its printed face blows a kiss and dissolves against the otter’s damp skin. Her breath finishes with a rough little sound. She asks for Marta before she asks about the date. Anima writes both requests down. ","The doctor brings out a practice apparatus built from a drawer runner, jars, and a sterilised clamp. Two named beads stand for Ada’s brain and Supine’s brain; a third stands for the unwritten organ from the Pit. The actual exchange will move wet living brains, with their nerves released and their tissue held in the shuttle. Supine has a large opening in her human head. The named organ will be carried through that opening into the place her brain occupied, while hers enters Ada’s opened skull. ","A later removal needs a speaking jar for Supine and a temporary living organ in Ada’s body while her own brain returns. The signature readers must identify minds rather than their expected faces; clamps must secure the receiver before anything travels. Morrow listens without offering the use of her own head. “Plan getting her out,” she says, looking at Ada. The apparatus contains no living organ now. Reconstruct its safe sequence before the doctor will permit it to become a sequence with blood on the clamp."],task:"Arrange the seven practice-apparatus events in order. The named beads model people; this rehearsal moves no living brain.",evidence:[{title:"Timing marks",text:"Two events, exactly, stand between waking the empty cradle and shuttling the named mind. The bed latch is released immediately after both signatures have been confirmed. These marks belong to the empty practice apparatus, not a living operation."},{title:"Interlocks",text:"The receiving cradle is latched after the reciprocal echo test and before the named mind moves. Current signatures are read, and the empty cradle awakened, before that echo test. No arrival may be inferred merely from the bead’s expected destination."},{title:"The witness strip",text:"Waking the empty cradle is not the first event. Both signatures are confirmed only after the named mind moves. Each of the seven cards records a single event once; none stands for additional concealed steps."}],board:{kind:"sequence",cards:[{id:"latch",title:"Latch the receiving cradle",description:"The destination is physically secure before transport."},{id:"release",title:"Release the bed latch",description:"The model may leave only after both named endpoints are confirmed."},{id:"echo",title:"Test the reciprocal echo",description:"Both ends answer the same call without exchanging identities."},{id:"read",title:"Read current signatures",description:"Begin with the minds who are here now, rather than their expected bodies."},{id:"confirm",title:"Confirm both signatures",description:"Each person remains accounted for at the destination."},{id:"shuttle",title:"Shuttle the named mind",description:"The bead travels in its locked channel with its own name."},{id:"wake",title:"Wake the empty cradle",description:"A receiving space becomes ready without being called a person."}],solution:["read","wake","echo","latch","shuttle","confirm","release"]},hints:["The two events between waking and transport must include the echo and receiving latch. The two final events form their own fixed pair.","Waking cannot come first. Fit read before wake, then echo and latch between wake and transport. Confirmation and release complete the order.","Read signatures → wake cradle → test echo → latch receiver → shuttle named mind → confirm both signatures → release bed latch."],resolution:["Both named beads arrive correctly. Ada asks for a written stopping rule: if either mind’s signal disappears, no one continues by guessing. Anima writes it large enough to read above the apparatus. Morrow declines further testing, and her refusal ends the question. The rehearsal has produced a sequence, receivers, and a limit. It has not made opening Ada’s skull less terrible or made Supine’s thoughts less dangerous inside it. When living tissue replaces these beads, every name on the practice strip will still need somewhere to remain."],minutes:s},{id:"patient_return_route",title:"Prepare a way home",narrative:["The Hospital’s service corridors began as paths between parked caravans. Over time, roofs were added across them, tarpaulins replaced with thin board, and washing bays converted into recovery rooms. Reed’s seven-by-seven plan records the current passages, including closed units. An empty carrier must pass clean receiving, warmth, voice verification, and a booked return space in that order. It rehearses the arrival of an unwritten organ from the Pit. Bringing one here before preparing its cradle would leave living tissue waiting beside a locked door.","The plan separates incoming and outgoing lines. Repeating a square crosses them and leaves the return unprepared. The porter has thirty-two moves before his scheduled delivery; thinking through the route does not spend them. Brindle checks the carrier’s wheels, one of which has been taken from a child’s discarded pushchair. He will move the actual jar when the route has been approved. ","Ada has heard the castle described as the difficult part. Reed points to the booked return bed. The castle can be entered by a gap in a patrol; a small bed needs staff, heat, records, and time that nobody has allocated. Pip writes HOME IS ALSO A DESTINATION at the top of the plan, then underlines it once. The procedure cannot finish at the moment somebody leaves Supine’s room. Ada will still have to arrive here."],task:"Route the empty carrier through four preparation stations in order, then to the return bay. Move orthogonally, never repeat a square, and use no more than 32 steps.",evidence:[{title:"Service plan",text:"Enter at row 1/column 7 and finish at row 7/column 1. A closed bay cannot be used. Each move reaches one horizontally or vertically adjoining square and consumes one step from the thirty-two-step allowance."},{title:"Four stations",text:"First clean receiving at row 2/column 6; then warmth at row 6/column 1; voice verification at row 4/column 6; and return booking at row 7/column 4. Visiting in this precise order prepares the next station instead of leaving it to somebody arriving later."},{title:"Return requirement",text:"A future station cannot be touched early. No square may occur twice, including start and finish. Arriving at the finish before the preparations are complete therefore cannot be repaired by leaving and returning."}],board:{kind:"route",width:7,height:7,blocked:[0,1,2,3,4,15,19,22,29,31,38,39],start:6,end:42,waypoints:[12,35,26,45],maxSteps:32,solution:[6,13,12,11,10,9,8,7,14,21,28,35,36,37,30,23,16,17,18,25,26,27,34,41,48,47,46,45,44,43,42]},hints:["After warmth, keep row 7 free for the final approach. Reach voice verification through the middle passages.","Use row 2 to cross to the left edge. From warmth go right to column 3, up to row 3, then turn across toward voice verification.","From start: down 1, left 6, down 4, right 2, up 3, right 2, down 1, right 2, down 3, left 6. This visits every station in order in 30 steps."],resolution:["Brindle pins the approved route over the carrier. A warmed cradle and a return bed are reserved; the speaking jar bears Supine’s name. Her brain will remain a named person inside it even after it has been lifted from Ada’s skull. Reed checks that the jar’s acoustic tube lets its occupant interrupt. Anima refuses a spare from any patient in this ward. The Pit must supply a living organ that has never belonged to someone. The route is ready. The bodies that will need it are still elsewhere, and the nurses are already tired."],minutes:s},{id:"patient_two_voices",title:"Neither person disappears",narrative:["The last rehearsal uses a five-by-five witness board. Two complete vertical lines belong to the two named minds. Its indicators have been scrambled deliberately, so neither appearance nor an expectation of where somebody should be can supply the answer. Anima runs a finger over the names beneath them. The board can only certify whether each signal remains accounted for. It cannot tell you that the person arriving has become somebody you hoped she would be.","Ada asks whether Supine will be kinder in a hare’s body. Anima says her brain will remain her own. Her beautiful human body may live without a brain; Ada’s cannot. That is why the later extraction needs a replacement organ ready before Supine’s tissue is removed. Changing who inhabits the Lady’s head may change what the God Switch obeys. It will not undo a single hunger or make Supine’s contempt fade because the new face has ears. Ada listens without pretending this reassures her.","Pip asks if the speaking jar can hear, and Anima checks its tube instead of simply promising. Brindle asks who will lift Ada onto the return carrier if she cannot stand. He puts his name in that field. Restore both witness lines with the complete switching rule. Diagonals do not change; double presses cancel. Its purpose is to keep you from learning those facts by losing someone on the live apparatus."],task:"Restore both outer columns of witness lamps, matching the target. Pressing one switch toggles its lamp and the four orthogonal neighbors.",evidence:[{title:"Witness board",text:"Both outer columns must be fully lit: all five cells of column 1 and all five of column 5. Every cell in columns 2, 3, and 4 must be dark. One surviving line cannot substitute for the other named mind."},{title:"The switching rule",text:"Pressing reverses the selected cell and its existing immediate neighbours above, below, left, and right. Diagonals stay unchanged. Repeating a press twice cancels its effect, and changing the order of different presses does not change the result."},{title:"Anima’s reminder",text:"Compare each lamp with its specified target. Darkening every lamp would erase both required witness lines. The living procedure stops if either named signal disappears; the empty model lets that rule be learnt without losing anyone."}],board:{kind:"circuit",size:5,initial:f([1,3,6,8,10,12,14,16,18,22,24],b),target:b,solution:[1,3,6,8,10,12,14,16,18,22,24]},hints:["Separate desired light from unwanted light. The two outer columns must remain lit even when nearby switches affect them.","One solution starts by pressing R1C2 and R1C4. It also presses R2C2 and R2C4; the remaining seven presses lie in rows 3–5.","Reset, then press R1C2, R1C4, R2C2, R2C4, R3C1, R3C3, R3C5, R4C2, R4C4, R5C3, R5C5 once each, in any order."],resolution:["Both lines become steady. Anima signs the rehearsal, leaving the consent boxes empty for Ada to answer later. Morrow returns to stillness with the cuff in her hands and the flowers beside the pane. Her chart now has a name, but no new supply of waking time. The doctor rejects the classification that would have made her a spare. A missing yesterday does not make an unwritten brain. If the Pit supplies an organ, he will examine its whole history. Silence is not evidence that nobody has ever lived inside it."],minutes:s}],conclusion:["Marta is sent word that her sister remains herself. Reed keeps the repaired charts at the beds. The sorter stays unplugged. Forty-four minutes have supplied one eight-minute waking and the work needed around it; the rest of Morrow’s future is still withheld. By the time you leave, the biscuit tin is light, and the flowers cast almost no shadow through the rain-dark plastic. Reed closes the pane before its damp reaches the blanket.","You have a procedure whose outward and return journeys name the people inside it. Ada must decide freely. Her brain must come home. Supine’s removed brain must retain a speaking jar, a name, and the ability to refuse. The spare organ must never have belonged to somebody. Brindle has booked the carrier; Pip has written the stopping rule again in ink that will not wash away. Anima takes the practice beads out of the clamps. The next material the apparatus carries will be alive."]}],d=e=>e.trim().split(/\n\s*\n/),v={palace_ledger:{narrative:`Ada finds the duty register in a medicine cupboard labelled NO PRIVATE READING. The door has been taken away to repair a floor. Five Aristobats are named, although only two hang above the entrance. The others listen through rubber tubes buried in walls assembled from caravan panels and packing board. Their hearing is excellent. Their judgment has been replaced by this register. A sigh at the assigned station proves satisfactory repose; the same sigh elsewhere is entered as a possible grievance. The hours beside the names continue beyond the space allowed for a shift.

Brindle carried these tubes uphill years ago. He was told they were heating pipes. One still bears the dent where his horn steadied it, beneath a skin of gold paint. The hospital had been cold that winter. He remembers saying that somebody would be warm at last. He folds the cloth over his horn and cannot look at Ada. Pip puts a wing against his wrist. Neither of them finds a sentence that can make the work harmless now. In the next room somebody coughs and immediately apologises to the tube.

The relief slips have lost their station labels. Reconstructing them will tell you which harmless sound each minder has been trained to accept. A recognised relief is the only opening the machinery permits. Loudness would punish the ears of people already kept awake for days. Brindle has brought a little food, wrapped in pages from an old permit. The gate of a palace should not depend on whether a tired guard has eaten. Here it might.`,resolution:"The five assignments fit. A pencil stops moving behind the wall. “Relief acknowledged,” says a voice so worn you mistook it for the draught. Quill asks whether food is included. Brindle opens the bag: enough, if he does not eat. He gives his portion away before anybody can count it. The first opening in the Great Castle Divine is the width of a cupboard door somebody could no longer afford to keep."},palace_cipher:{narrative:`Inside the register is a smaller book printed before Supine's face became the watermark of every official sheet. Instructions for a Room Containing a Person is stamped on its cover. Person has been crossed out and replaced with Presence. Someone tried to restore the first word with a wet pen; the paper tore. Through the tear you can see the numbered lines on the other side. A corner has been burnt, probably beside a heater kept too close to a bed. Even the palace has never had enough sockets.

Pip reads quietly. The old instructions insist that a camera is not company, a chair is not a duty, a doorway need not be an altar. Those are things a person should have been able to say without a code. Ada recognises the index from clock inventories: a word survives as coordinates while a censor sees a harmless table. Under the copyist's signature is a second stamp, EMPLOYMENT ENDED. Nobody has written a forwarding address. The moth smooths the page as if the absent hand might still need room to finish.

The register requires two words before it will recognise an interval without observation. One describes the interval; the other admits a visitor. Neither conveys ownership of the room or the woman inside it. Ada keeps the doctor's continuity plan beneath the book. Beyond the door waits an actual human body, with an enormous head and an opening through which a living brain can be removed. There is nothing figurative about what you intend to do. Decode the old pause in watching before you bring that plan any closer to her flesh.`,resolution:"The two words leave a narrow legal interval in which a body need not produce an image. Pip copies them on the back of a ration notice. “Somebody lost their place for writing this,” he says. The register does not contain a reinstatement procedure. Ada puts the words beside the doctor's plan. You have recovered an instruction, not the person who first tried to make it ordinary."},palace_balance:{narrative:`The palace walls are lined with felt salvaged from mattress undersides. It has been fitted to carry sound inward. Outside, an Aristobat hears a tenant whisper through a thin wall. Inside, Supine's smallest movement passes into a speaking tube. Brindle rests a palm against one panel. It gives under his weight; a strip of painted paper is the only thing joining it to the next. The Great Castle Divine is a row of old trailers with its gaps declared decorative. Its listening system is better maintained than its plumbing.

The maintenance panel lists five ways to interrupt the carrying: soften a wall, cradle a bell, slacken a drum, lay water under a tube, cushion the watching chair's runners. Allocations are measured in beats because the devices must share a rhythm. Too little leaves a live channel. Too much announces an obstruction. Ada copies all five calibration conditions before the display replaces them with the Lady's face. A loose wire behind the display ticks against exposed metal. There is a notice forbidding workers to mention that sound on Channel 9.

The runners have worn through the floor where Supine stands up and sits down to remain visibly available. Nobody has installed a setting for being tired. Brindle offers the low hum he uses while repairing somebody's last chair. It can occupy a listening tube without damaging the listener. He is hungry enough that the first note shakes. Pip holds the water tray level. Allocate the masking beats precisely; a failed calculation will make all their small efforts legible to the wrong people.`,resolution:"The hum reaches every tube at its permitted strength. Ticking and sighs stop arriving as offences. Behind the glass, an Aristobat removes his duty collar. The fur beneath it has been rubbed away. He asks how long the relief lasts, then sits before you can answer. Brindle lowers his voice to save his breath. The interval is sufficient for your visit. It will not restore the years these rooms have taken from anyone."},palace_sequence:{narrative:`Seven handles have been screwed into an old kitchen counter. The labels call it the Divine Control Desk. Beneath the gilt edging you can see the ring left by a hot pan. A card warns that an unauthorised sequence will be broadcast as an attack on the Lady. A later card corrects the first: any sequence absent from the register is unauthorised. There is still a blank line. Relief has survived as a procedure so burdensome that nobody has the strength or spare hours to request it.

Each handle protects against a different accusation. A witness establishes that the room has not been abandoned. The mirror supplies a truthful camera view without showing Supine's face. Water steadies that image. The bell releases the minders. A curtain covers the bed. A broadcast retires the public claim to watch her. Finally, the guest bell allows the inner door to answer. The mechanism reads actions only in their recorded order. A curtain drawn too early becomes concealment; a door opened too early becomes intrusion. Care has been divided into offences and then sold back as permission.

Ada refuses to register you alone. “They will put whatever happens afterward under one name,” she says. Pip signs beside you. Brindle's mark is difficult because his hand has started to cramp. The three signatures will remain here even if you leave. You are accepting responsibility for entering a real woman's room and handling her brain, not consenting to carry the blame for every choice she has made. Arrange the relief while that distinction still has a place on the form.`,resolution:"The seven actions satisfy both memoranda. Channel 9 briefly shows an empty chair with a correct label. Its audience counter remains enormous until the unit changes from viewers to connections. A country of unattended screens has been described as devotion. Pip asks who first recorded the distinction. The signature has been cut out. You leave the usable order on the desk, where another exhausted person might find it before their remaining time runs down."},palace_route:{narrative:`The plan unfolds in layers: the caravan floors, the listening wires, the camera cones, then a route labelled NOT CURRENTLY REQUESTED. The live sightlines are black. They crowd a corridor empty of bodies. Replacement panels have shortened two rooms and widened a passage that no longer reaches a door. Ada traces the remaining open tiles. The castle has been “updated” by workers paid to cover the last worker's repair. Every change has acquired a plaque. None has made a private place to sleep.

The route must pass four witness stations in order. The felt landing confirms softened sound. The water mirror confirms a truthful camera view. The curtain cleat confirms that no sleeping face appears in it. The guest bell confirms that a person is entering. A later confirmation cannot replace an earlier one. You must cross this little model according to its rules before the real corridor will cease reporting footsteps as an emergency. Black tiles contain live sightlines or acoustic wires, however harmless the patched surface looks.

Brindle holds the curtain. Pip stays by the desk with the relief book, ready to answer if a minder asks a real question. Ada walks with you. Through the wall comes a fingernail tapping the chair arm: the noise of someone fighting sleep because sleep will be noticed. At the bend a little screen shows Supine's enormous human head from above. A dark aperture opens through its crown. That is where the exchange must happen. You have eighteen safe steps to reach the door. Ada's ears flatten as she sees where her own brain is supposed to go.`,resolution:"The guest bell sounds once. There is no announcement. Ada presses her palm against the wall until her breathing steadies. Supine asks from inside whether the broadcast has broken. You can tell her it has been relieved. That small truth is all the room can bear yet. The corridor remains passable on the return journey; nobody will have to remain at a station merely because they helped you reach the last one."},palace_circuit:{narrative:`Twenty-five little lights burn above the inner door. Their claims include public reassurance, archival continuity, medical supervision, protection of property, and protection of the image certifying that property. Switching one claim off wakes its neighbours. The circuit has been mended so often that the wires no longer match their colours. It still serves its purpose: there is always another reason to keep a woman under observation. There is never a box for her permission.

Supine says the recordings began with a wonderful day. Later each day was compared with it. Eventually she arranged her face before a camera came on. “Nobody made me,” she says, quickly. You hear the chair shift. Then she asks whether the old recordings could tell a decision from something she no longer remembered choosing. Behind the question is the human ruler who made other people's exhaustion a broadcast spectacle. Her own captivity does not return the minutes she took. It does not make the hospital beds empty.

The relief register authorises every shutter, but the circuits remain coupled. Darken the grid without breaking the equipment needed for fire or illness. A pause in surveillance will let you approach her enormous open-topped skull. It will not replace Ada's consent, the doctor's safety protocol, or a promise to bring both brains back alive. Brindle's lullaby is waiting outside. He learnt it in a room where five people shared one heater. The tune has never caused a listener to be less hungry.`,resolution:"The last lamp goes dark. Supine stands, sways, and sits heavily on the bed. From this close, the opening at the top of her immense head is plainly an opening in a body. “You will say it was beautiful,” she tells you. Pip has no reply ready. Brindle begins the lullaby softly enough that it could be missed. You have ended the scheduled audience. The living brains, the exchange, and Ada's way home remain ahead of you."},last_ledger:{narrative:`The last gate opens an account book to MINOR REMAINDERS. Ada lays it across her knees between Pip and Brindle. Her own brain is back inside her own skull; the stitches still hurt when she turns. Supine's mind has been removed from Ada's body and kept living in its jar. Ada says little about the things her mouth said while it belonged to the Lady. She remembers hearing them from the huge human body in the castle and being unable to take her own hands away from their author.

Each entry describes unfinished work, then gives a reason to seize its owner's reserve. A poem may be abandoned. A bench can wait. A repaired curtain is not essential. These are protected entries from the returned reservoir, not new payments. They do not alter the time in anybody's pocket or undo your decision about the friends' pledge. The gate needs the correct owner before it will stop presenting that reserve to the next impressive claimant. Five people have sent evidence: Pip's cramped handwriting, Brindle's page folded around a splinter, Ada's diagram of a spring that cannot be taken without stopping its clock.

Mrs. Thimble sends a piece of curtain whose old lining has been patched with flour sacks. Vellum sends a catalogue heading for a missing book. None calls the work grand. These were the things they hoped to finish before their heads hit the pillow. Reconstruct the five entries so a person can own that small remainder of a life without proving it would please the Lady. The gate will not account for the projects already abandoned by people who cannot answer.`,resolution:"Five reserves find their living owners. Pip touches the space beside his poem. Brindle says the bench needs one more rung because a sleeve could catch there; he can still imagine someone sitting down. MINOR REMAINDERS is replaced by RESERVED BY THEIR OWNERS. The heading leaves the old confiscations intact above it. Ada does not cross them out. There are people for whom correcting this ledger has come too late."},last_cipher:{narrative:`Beneath the polished refusal, another inscription survives where the cleaning brush could not reach. Its lettering is practical, poorly centred, and close enough to the floor for a waiting traveller to touch. The threshold was first built from a service door and two lengths of gatepost. Later it was clad in imitation marble. A third renovation covered the hinges and left the door harder to open. The surviving charter has eight lines and two operating instructions disguised as an index. You can read it only by kneeling beside a drain.

Lady Supine watches from the living jar. “I did not order those words removed,” she says. Ada believes her. One clerk improved the surface, another improved the record, and a third decided the improvements were the reason the entrance existed. “You kept what it took,” Ada says. Supine turns toward the gate. In Ada's body she called the hospital patients animals and demanded that Brindle stop touching her coat. Now the same mind needs Brindle to steady its little container against the wind. He does it without calling her kind.

Pip reads the charter in a tired voice. It does not promise everlasting life. It describes a person, a promise, and the day that might follow. The indexed words are instructions, not a verdict on whichever ending you prefer. Decode both before asking the gate to interpret its final rule. You are retrieving something a hungry traveller might once have read while waiting here. There is no assurance the traveller was admitted, or had enough time left to stand afterward.`,resolution:"The old vocabulary opens the accounting drawers. Supine asks whether it applies to her too. Ada says an owner must be heard even when hearing her is difficult. Brindle folds part of his empty coat beneath the jar so its glass will not scrape the threshold. The Lady asks for a cushion. This is the only one. The recovered charter cannot promise a kinder speaker, only a rule that need not depend on liking its subject."},last_balance:{narrative:`Five envelopes slide from the gate. Their seals carry Supine's smiling face. Each face blows a kiss as the glue loosens; the printed mouth dissolves and the paper smells faintly of scorched hair. No new time arrives. These are receipts for ninety minutes already held from travellers the threshold refused. The portraits have survived the people who once watched them dissolve in the hope of staying awake another night. Even the return has been arranged to look like the Lady's generosity.

Ada spreads them beneath the ledger. There is an ordinary household, a suspended patient's claim, the gate's existing price, a common remainder, and a disputed refund. Names have been withheld so publication will not expose people already frightened of a knock at their thin door. The surviving relationships are sufficient to reconcile the amounts. Your friends do not pay again. Nobody at the hospital needs to be found less deserving so another person can be counted. The five envelopes partition funds already in escrow; the total is not a measure of all that has been lost.

The gate calls the calculation an allocation. Ada calls it evidence. You have not chosen which claims should continue or what a shared account might become. Establish what is here and owed before deciding. Brindle shields the envelopes with his body. Pip puts a chipped cup on one corner, the cup he brought in case there was anywhere to make tea. It is empty. Nobody tells him he should have travelled lighter.`,resolution:"The ninety minutes reconcile without another payment. Thirty remains the old threshold price; appearing in an envelope cannot make the toll fair. Ada writes CALCULATION COMPLETE, AUTHORIZATION PENDING across the seals. A total has become information instead of an immediate order. It is a small reprieve. The hospital claim is still a patient who has waited, the household still a room with a failing roof, and ninety minutes will pass even when returned honestly."},last_sequence:{narrative:`The closing instructions lie on two pages. One belonged to an account clerk; the other belonged to an appeals clerk who tried to keep the first clerk's decisions reversible. Neither bears Supine's signature. Both bear her seal. Staples from later corrections have turned the margin into a perforation. Through it you see the threshold's timber core. This is how the country was enlarged: the same authority, another sheet, a repair that made the previous damage somebody else's responsibility.

Seven actions protect different things. An original establishes a person. Copies must be identified before a doubled claim makes a reserve look excessive. The reserve must be sealed before a conditional pledge is released. The public receives an honest total while private owners keep their names. A shared account may then be authorised from what can freely be shared. The last action keeps the decision open until everyone knows what has happened. A shortcut could convert your friends' generosity into a method of collecting from them.

The order preserves either decision you made at Brindle's bench. An accepted pledge can return to its living owner. An unspent offer need not become a charge. Pip says that offering the last of something was not asking to disappear. His voice almost fails on the last word. Brindle knew what the offer meant when he made it. Ada has stopped looking at the place where she put her spring. Arrange the pages before their decision is filed as evidence that a person can manage with nothing.`,resolution:"The pages form a usable order. A refund is no longer disguised as a gift, nor a total as permission to seize its parts. VALID FOR MORE THAN ONE PERSON appears on the gate. The phrase has been possible all these years. Pip takes Brindle's hand and holds it too tightly. Ada enters four names, then a place for the additional witness. Supine asks for hers. You can hear it without forgetting anybody she refused to hear."},last_route:{narrative:`Seven rows unfold from the floor before the gate. The black tiles carry small ownership claims: the road belongs to its toll, the name to its register, the promise to whoever can collect it. Under the printed declarations is ordinary patched linoleum. People have been prevented from walking by sentences affixed to a surface other people laid. The model will accept an approach that avoids those claims. It will not apologise for the years in which it accepted no such route.

Four stations remain on open tiles. A name must be heard before its reserve is protected. Protection comes before recognition of an offer freely made. The offer comes before the final choice is left open. Entering a station early repeats the gate's old practice of recording consent after the money has gone. Move through the model in the prescribed order. The black squares are closed; each safe square may be used only once. A route can look direct and still omit the person it claims to serve.

Your companions wait while you trace it. An incorrect trial will not spend them. Brindle holds Pip's poem against the wind. Ada supports the jar with a hand that Supine recently used to point people out as vermin. Supine asks to see the board more clearly; Ada adjusts it without answering. Sixteen moves are available. The route ends at a threshold, not proof of a country worth entering. Outside the model, the road back to the trailers is still open and still long.`,resolution:"Each witness reaches the threshold in order. Four people have not been combined into a larger purchaser. Supine calls the route inelegant, then asks whether elegance was a condition. Ada checks. It was not. The Lady watches the path without correcting it. You have shown that an approach can include a protected life and an uncollected offer. That possibility does not restore the people who wore this floor down waiting for it."},last_circuit:{narrative:`The final drawer contains a grid like the castle's. There it assigned watchers to every movement. Here it assigns a proprietor to every possible next moment. A lit square proves no future exists; it records someone claiming the right to sell one. Each neighbouring claim sustains another. The collector requires a keeper, the keeper a register, the register a gate that turns travellers away. Old wires have been joined with household tape. None of the people who repaired them could afford the thing they kept selling.

The panel is a simulation, disconnected from the real reservoirs. Darkening it will show that an account can remain legible without a single owner. It will not choose a commons, an unmeasured country, or home. Supine understands the difference before anyone explains it. “You could leave it like this,” she says. “And still decide to go back.” She sounds offended that a mechanism might work without commanding its users. In Ada's body she demanded a return to the palace. In the jar, with no hands to enforce that demand, she has to wait.

Pip says he would like to finish a poem somewhere he can sleep. Brindle says the bench will need a roof before winter. Ada looks at the little coupled lights instead of offering another analogy. A common future would still need repairs, food, and people willing to do the work without owning everybody afterward. Clear the claims while leaving the counting mechanism intact. Whatever you choose, it must not require another divinity to sell your friends the minutes they have left.`,resolution:"The grid goes dark. The account remains readable. No name disappears and no patient loses a reserve. Supine asks what a Keeper would do here. Nobody finds a reassuring answer for her. Pip quietly asks Brindle whether the old kettle can be mended; Brindle says they can try. You close the drawer. The last gate has enough information to hear your choice. There will still be weather, exhausted bodies, and things no corrected account can give back."}},W={palace_ledger:[{title:"Station plan",text:"From west to east the five posts are Bell, Chair, Door, Window, Pipe. Every minder occupies exactly one post and expects exactly one sound; every post and sound is used once."},{title:"Relief slips",text:"Rook stands immediately east of Hush. Velvet stands west of Hush. Sable stands east of Rook. Quill does not occupy Window."},{title:"Sound observations",text:"Hush expects Tick. Hum comes from immediately east of Rain. Sigh comes from immediately east of Tick. Chime does not come from Bell. Velvet does not expect Rain."},{title:"Unpaid relief",text:"The shift sheet has no column for the hours after the scheduled replacement failed to arrive."}],palace_cipher:[{title:"Eight lines of the relief book",text:`1. Under the cameras every sleeper must pretend that stillness is praise.
2. No window opens until someone has approved the shape of daylight.
3. We record each silence because no one should be lonely unseen.
4. The chair remembers a woman who once preferred a crooked drawing.
5. Children may finish songs when an adult cannot bear their ending.
6. Let curtains shelter ordinary faces without announcing whose eyes are closed.
7. A welcome requires a door and somebody willing to hear footsteps.
8. The watchers deserve a morning that does not depend on watching.`},{title:"Indexing rule",text:"Each group means line.word.letter, counted from one. Count words separated by spaces; ignore punctuation. Take that letter, then read groups from left to right. MODE and REPLY are separate words. Nothing is reversed or shifted."},{title:"Missing copyist",text:"The book bears EMPLOYMENT ENDED beneath its copyist’s signature. The old instructions survived where their author did not."}],palace_balance:[{title:"Measured quiet",text:"These are beats of masking rhythm, not stolen minutes. Every station receives a whole, nonnegative number of beats. All five station allocations are separate; do not count a combined observation as a sixth station."},{title:"Calibration restrictions",text:"The five conditions shown beside the board all hold at once. A larger total can be louder even when its sources are softer. Keep the total at forty-four; the relief bell will reject both overfilling and underfilling."},{title:"Maintenance priority",text:"Every listening tube has a current inspection stamp. The heater beside the panel is marked REPLACEMENT DEFERRED."}],palace_sequence:[{title:"Camera memorandum",text:"Mirror is immediately before Water. Exactly one action occurs between Water and Curtain. Broadcast occurs after Curtain, but Broadcast is not last. Door occurs after Broadcast."},{title:"Relief memorandum",text:"Witness is earlier than Mirror. Bell occurs after Mirror and before Curtain. Every action happens once; all seven positions must be filled. The memoranda describe one schedule, not two alternative schedules."},{title:"Accumulated repairs",text:"The Divine Control Desk is an old kitchen counter. Seven handles have been added through the burns left by somebody’s meals."}],palace_route:[{title:"Observation tiles",text:"Black tiles carry a live sightline or an acoustic wire; crossing any of them alerts a minder. Other tiles are safe. Move horizontally or vertically, without revisiting a tile. The drawing uses an eight-by-eight floor."},{title:"Witness stations",text:"Visit the four numbered stations in order: felt landing, water mirror, curtain cleat, guest bell. Then reach the inner door. You have eighteen steps, including each move from the starting tile. A later station cannot be entered early."},{title:"Room alterations",text:"A caravan window has been covered by the latest observation panel. Its latch remains on the wrong side."}],palace_circuit:[{title:"Coupled shutters",text:"Pressing a shutter flips that square and its orthogonal neighbours. Corners have two neighbours, edges three, interior squares four. Diagonals never change. The lamps must all be dark; a lamp indicates observation, not illumination."},{title:"Keeper’s correction",text:"A press can be undone by pressing the same square again. Work across the top row, then use the row below to clear any remaining lamps above it. The lowest row determines whether your chosen top-row presses were right."},{title:"Recording archive",text:"The archive marks Supine’s sleepless nights CONTINUOUS AVAILABILITY. No entry uses the word exhaustion."}],last_ledger:[{title:"Five unfinished claims",text:"Each person has a distinct reserve from 6, 7, 9, 12, 16 minutes, and a distinct project: Poem, Bench, Repair, Curtain, Catalogue. These are documented protected reserves, not new charges on your pocket."},{title:"Amount cross-references",text:"The Bench reserve exceeds the Poem reserve by two. The Curtain reserve is twice the Repair reserve. Vellum has the greatest reserve. Ada’s reserve is smaller than Pip’s."},{title:"People cross-references",text:"In ascending order of reserves, Thimble immediately follows Brindle, and Vellum immediately follows Thimble. Pip’s project is neither Curtain nor Repair. Ada’s project is not Poem. Thimble’s project is not Catalogue."},{title:"Unanswered names",text:"Earlier confiscations remain above the living owners’ claims. The gate has no address for people whose time ran out."}],last_cipher:[{title:"Eight lines of the first charter",text:`1. A minute belongs to whoever is alive enough to spend it.
2. A promise belongs to everyone whose name can answer its invitation.
3. The future is no cupboard for the richest hand to lock.
4. Even a borrowed watch should return with its owner still present.
5. We can share a road without making every footstep last forever.
6. There are endings that open windows instead of settling all accounts.
7. Keep one chair empty because another traveller may still be coming.
8. Let each tomorrow begin where somebody asks how you slept tonight.`},{title:"Reading rule",text:"Each group means line.word.letter, counted from one. Words are separated by spaces and punctuation is ignored. Read each indicated letter in order. MODE and REPLY produce two separate words. Do not change, reverse, or substitute any letters."},{title:"Replacement cladding",text:"Imitation marble covers the old service door. Only the lettering near the drain escaped the successive improvements."}],last_balance:[{title:"Existing funds only",text:"The ninety minutes are already in the gate’s escrow. No friend pays into this calculation. These five envelopes are a model of the escrow’s obligations, and they partition it completely. Use whole, nonnegative minutes."},{title:"What the envelopes do",text:"Return marks a disputed refund, Hospital a suspended patient’s claim, Household an ordinary livelihood, Threshold the existing gate price, Common a remainder no single owner may seize. The equations establish amounts; they do not authorize spending them."},{title:"Dissolving seal",text:"The Lady’s smiling seal survives every collection. The gate recorded no condition of the traveller when admission was refused."}],last_sequence:[{title:"Account clerk’s marginalia",text:"Choice is last. Pool is immediately before Choice. Copies is immediately before Protect. Refund occurs exactly two positions after Copies. Original is before Copies."},{title:"Appeals clerk’s correction",text:"Refund is after Protect and before Declare. Declare is before Pool. Each action occurs once. An offered reserve must be protected before its conditional pledge is released; publication is never permission to confiscate."},{title:"Authority renewed",text:"Neither clerk signed in the Lady’s name. Each correction carries her seal, including the corrections to the previous correction."}],last_route:[{title:"The final floor",text:"Black tiles are one-way ownership claims painted onto a floor that allows only ordinary walking. Avoid them. Move orthogonally, never revisit a tile, and visit numbered stations in order before reaching the open threshold."},{title:"Four witnesses",text:"The stations record a name, a protected reserve, an uncollected offer, and a choice left open. Their order matters: ownership cannot be renounced before its owner is heard. The seven-by-seven plan permits at most sixteen moves from the starting tile."},{title:"Worn approach",text:"The model rests on patched linoleum worn thin by waiting feet. Successful calculation cannot identify everyone who stood here."}],last_circuit:[{title:"Common routing",text:"A press toggles its own lamp and the lamps immediately above, below, left, and right when those neighbours exist. Every lamp must end dark. Darkness means no private proprietor is assigned; it does not mean the minutes are destroyed."},{title:"A reversible experiment",text:"These are routing simulations. You may undo a press with another press on the same square. Clear a high row by pressing beneath its lit lamps. If the bottom row remains lit, reconsider the initial top-row choices rather than spending anyone’s time."},{title:"Repaired wiring",text:"Household tape joins the oldest wires. Whoever made this repair could not afford the minutes the mechanism was selling."}]};function h(e,t){const[a,n]=F[e];return{id:e,title:a,task:n,narrative:d(v[e].narrative),evidence:W[e],board:t,hints:j[e],resolution:d(v[e].resolution),minutes:{min:3,typical:5,max:9}}}const F={palace_ledger:["The ears assigned to the walls","Reconstruct the five minders’ posts and expected sounds."],palace_cipher:["A vocabulary for being unseen","Decode the relief register’s mode and reply words."],palace_balance:["A measured roomful of quiet","Allocate the masking beats so every calibration condition holds."],palace_sequence:["The order permitting an interruption","Arrange the seven relief actions into the one authorized schedule."],palace_route:["The room between observations","Trace a safe route through the observation floor."],palace_circuit:["One interval without an audience","Darken all twenty-five observation lamps."],last_ledger:["The lives entered as remainders","Match every protected reserve to its owner and unfinished work."],last_cipher:["Words under the replacement panels","Decode the original charter’s two surviving instruction words."],last_balance:["Ninety minutes already here","Reconcile the five envelopes without charging any friend."],last_sequence:["A reserve before its collection","Arrange the seven accounting protections in their lawful order."],last_route:["Four people through one sentence","Bring the four witnesses to the threshold in the required order."],last_circuit:["An account without a Keeper","Remove the final grid of exclusive ownership assignments."]},j={palace_ledger:["Begin with the adjacent pairs: Rook after Hush, and Sigh after Tick. Those two pairs describe the same posts because Hush hears Tick.","Try Hush at Chair, then at Door. The Rain-Hum pair, Chime’s restriction, and Velvet’s restriction eliminate the earlier placement.","Quill: Bell/Rain. Velvet: Chair/Hum. Hush: Door/Tick. Rook: Window/Sigh. Sable: Pipe/Chime."],palace_cipher:["Use the first number to find a numbered line, the second to count its words, the third to count letters within that word.","Punctuation is never a letter. For example, a final period does not add to the length of its word. Decode each label independently.","MODE is UNWATCHED. REPLY is WELCOME."],palace_balance:["Call the wall w and drum d. The bell is w+d, while the bell plus drum equals eighteen.","Use chair=w−1 and water=2d+1. The total becomes 3w+4d=44; compare that with w+2d=18.","Wall felt 8; Bell cradle 13; Drum skin 5; Water tray 11; Chair runners 7."],palace_sequence:["Broadcast must be sixth and Door seventh: Curtain precedes Broadcast, and Door follows it.","Water must be third, with Bell occupying the single gap before Curtain. Witness and Mirror fill the two earlier positions.","Witness → Mirror → Water → Bell → Curtain → Broadcast → Door."],palace_route:["Plan backwards from the fourth station and the inner door. Do not enter the fourth station while still collecting earlier ones.","The third station is reached from above, then the path bends east and north before approaching the fourth from below.","Rows and columns count from 1: (8,1) → (7,1) → (6,1) → (6,2) → (6,3) → (5,3) → (4,3) → (3,3) → (3,4) → (3,5) → (3,6) → (4,6) → (4,7) → (4,8) → (3,8) → (2,8) → (2,7) → (1,7) → (1,8)."],palace_circuit:["The grid is coupled: switch changes, not individual desired lamp states. Try clearing rows from the top.","A complete solution uses ten different switches. If you restart, its first-row presses are columns 1 and 3.","After resetting, press these row/column positions once each, counting from 1: (1,1), (1,3), (2,2), (2,4), (3,1), (3,3), (4,2), (4,4), (5,3), (5,5)."],last_ledger:["Only 6 and 12 can be the doubled Repair and Curtain pair. Only 7 and 9 can be the Poem and Bench pair.","Vellum has 16. The consecutive Brindle–Thimble–Vellum chain must therefore be 9–12–16. Ada is smaller than Pip.","Pip: 7/Poem. Brindle: 9/Bench. Ada: 6/Repair. Thimble: 12/Curtain. Vellum: 16/Catalogue."],last_cipher:["Each coordinate points at an actual letter in the charter. Keep a separate line of decoded letters for each label.","Use one-based counting for all three numbers. Spaces separate words; punctuation contributes nothing.","MODE is TOGETHER. REPLY is TOMORROW."],last_balance:["Let the Return envelope be r. Then Common=2r and Threshold=3r.","Hospital=r+8. Because Household+Hospital=Threshold, Household=2r−8. Sum all five envelopes.","Household 12; Hospital 18; Threshold 30; Common 20; Return 10."],last_sequence:["Pool and Choice occupy positions six and seven. Keep Copies immediately next to Protect.","Refund is one position after Protect. Original must precede that three-card run, and Declare must follow it.","Original → Copies → Protect → Refund → Declare → Pool → Choice."],last_route:["The first station is approached from its west side. Reach the second from below.","After the second station, move east twice and then south to the third. Circle its east side to approach the fourth from below.","Rows and columns count from 1: (7,1) → (6,1) → (5,1) → (5,2) → (5,3) → (4,3) → (3,3) → (3,4) → (3,5) → (4,5) → (4,6) → (4,7) → (3,7) → (2,7) → (2,6) → (1,6) → (1,7)."],last_circuit:["Each press affects a cross. Clear a row by pressing below its lit cells, rather than trying to clear it in place.","A complete solution uses ten different switches. On a fresh board its first-row presses are columns 2 and 5.","After resetting, press these row/column positions once each, counting from 1: (1,2), (1,5), (2,1), (2,5), (3,2), (3,4), (4,1), (4,5), (5,1), (5,4)."]},c=Array(25).fill(!1),y=e=>e.reduce((t,a)=>u(t,a,5),c),Y=[{id:"listening_castle",act:5,title:"The Castle That Watches Itself Sleep",subtitle:"Request one unwatched interval before the exchange.",location:"castle",premise:d(`At the servants' entrance of the Great Castle Divine, Aristobats hang in velvet uniforms whose lining has been repaired with hospital cloth. The palace is built around trailers with their wheels removed. Plywood turrets hide the old hitch plates. Through each room runs a system for listening, maintained more carefully than the heaters or drains. Cameras record Lady Supine, the actual human ruler, in a chamber with no recognised interval for sleep.

Ada finds an old relief procedure. It can release the minders, authenticate a record, and admit a visitor while keeping the Lady's face off the screens. It requires observation, calculation, and a route through a corridor almost filled by live sightlines. Every ordinary request has become so expensive to prepare that the tired people stationed here have stopped making them. You must use what remains rather than leave another failed repair behind.

Pip opens the relief book. Brindle puts down the food he brought from the shanties. Behind the screens waits Supine's real human body: enormous head, an opening at its crown, a living brain that can be exchanged with Ada's. A brain in the wrong body will still be the person who owns that brain. Getting through this door is only the first dangerous part of bringing your friend home.`),challenges:[h("palace_ledger",{kind:"ledger",rows:[{id:"hush",title:"Hush"},{id:"rook",title:"Rook"},{id:"velvet",title:"Velvet"},{id:"quill",title:"Quill"},{id:"sable",title:"Sable"}],columns:[{id:"post",title:"Listening post",options:["Bell","Chair","Door","Window","Pipe"]},{id:"sound",title:"Expected sound",options:["Rain","Hum","Tick","Sigh","Chime"]}],solution:{"hush.post":"Door","hush.sound":"Tick","rook.post":"Window","rook.sound":"Sigh","velvet.post":"Chair","velvet.sound":"Hum","quill.post":"Bell","quill.sound":"Rain","sable.post":"Pipe","sable.sound":"Chime"}}),h("palace_cipher",{kind:"cipher",inscription:`MODE: 1.6.2 / 8.9.5 / 3.1.1 / 4.2.3 / 5.10.1 / 7.2.4 / 5.10.2 / 7.11.7 / 6.11.6
REPLY: 2.2.1 / 4.7.4 / 1.9.5 / 6.11.1 / 5.4.2 / 1.6.1 / 1.4.3`,fields:[{id:"mode",label:"Mode word"},{id:"reply",label:"Reply word"}],solution:{mode:"unwatched",reply:"welcome"}}),h("palace_balance",{kind:"balance",fields:[{id:"wall",label:"Wall felt",min:0,max:44,suffix:"beats"},{id:"bell",label:"Bell cradle",min:0,max:44,suffix:"beats"},{id:"drum",label:"Drum skin",min:0,max:44,suffix:"beats"},{id:"water",label:"Water tray",min:0,max:44,suffix:"beats"},{id:"chair",label:"Chair runners",min:0,max:44,suffix:"beats"}],equations:["All five allocations total 44 beats.","The bell cradle receives the wall felt plus the drum skin.","The bell cradle and drum skin together receive 18 beats.","The water tray receives twice the drum skin plus one beat.","The wall felt receives one beat more than the chair runners."],solution:{wall:"8",bell:"13",drum:"5",water:"11",chair:"7"}}),h("palace_sequence",{kind:"sequence",cards:[{id:"door",title:"Open the inner door",description:"Only the room’s own guest bell may speak."},{id:"curtain",title:"Draw the velvet curtain",description:"The mirror must no longer return a live face."},{id:"witness",title:"Register a relief witness",description:"A named person accepts responsibility for the record."},{id:"broadcast",title:"Retire the public broadcast",description:"Channel 9 receives an authenticated still image."},{id:"water",title:"Set the water tray",description:"Its reflection absorbs the witness lamp."},{id:"bell",title:"Unhitch the duty bell",description:"The relieved minders may leave their stations."},{id:"mirror",title:"Turn the observation mirror",description:"The camera receives the patched room with no living face in it."}],solution:["witness","mirror","water","bell","curtain","broadcast","door"]}),h("palace_route",{kind:"route",width:8,height:8,blocked:[0,1,2,3,8,10,11,12,16,17,22,24,25,27,28,32,33,35,36,38,44,45,46,49,50,52,53,54,57,58,60,61],start:56,end:7,waypoints:[42,19,29,6],maxSteps:18,solution:[56,48,40,41,42,34,26,18,19,20,21,29,30,31,23,15,14,6,7]}),h("palace_circuit",{kind:"circuit",size:5,initial:y([0,2,6,8,10,12,16,18,22,24]),target:[...c],solution:[0,2,6,8,10,12,16,18,22,24]})],conclusion:d(`The castle remains standing: patched caravans, imitation towers, listening pipes. For the moment their attention no longer converges on one exhausted face. The minders eat the portions Brindle will go without. The corridor offers a return passage, and the guest bell can sound without the country hearing it.

You leave the relief procedure where others can find it. Beyond the door sits a real woman with an immense open-topped head. Ada checks the plan for moving living brains between bodies and returning each mind safely. She has not ceased to be afraid merely because the calculations work. Brindle begins the lullaby he learnt where there was never enough heat.`)},{id:"common_tomorrow",act:6,title:"The Last Ledger Belongs to Nobody",subtitle:"Keep the living owners out of the gate’s price.",location:"infinite",premise:d(`Your friends have offered their last time. Whether you accepted the pledge or asked them to keep it, you heard how little each had left. Pip's button, Brindle's string, and Ada's spring lie beside a ledger without a column for what surrendering them meant. Ada's mind is back in her own head. The Lady's living brain waits in a jar. The exchange has left marks on bodies that a returned entry will not remove.

The final gate holds ninety minutes taken from travellers it refused. Admission is still recorded as something one sufficiently wealthy person can purchase. Before deciding a future, read the surviving accounts: protected reserves, copied names, claims on funds already here, claims that presume authority. Some of the owners can answer. The books make no provision for finding those who ran out while their appeal waited.

Supine listens beside you. She has ruled this country in a human body and spoken through your friend's mouth. She remains the same mind in the jar. This inquiry will not prescribe a commons, the unmeasured country, or a return to the trailers. It can make those choices possible without using your friends as their price. First the gate must learn to count somebody who ought to remain alive afterward.`),challenges:[h("last_ledger",{kind:"ledger",rows:[{id:"pip",title:"Pip"},{id:"brindle",title:"Brindle"},{id:"ada",title:"Ada"},{id:"thimble",title:"Thimble"},{id:"vellum",title:"Vellum"}],columns:[{id:"reserve",title:"Protected reserve",options:["6","7","9","12","16"]},{id:"purpose",title:"Unfinished work",options:["Poem","Bench","Repair","Curtain","Catalogue"]}],solution:{"pip.reserve":"7","pip.purpose":"Poem","brindle.reserve":"9","brindle.purpose":"Bench","ada.reserve":"6","ada.purpose":"Repair","thimble.reserve":"12","thimble.purpose":"Curtain","vellum.reserve":"16","vellum.purpose":"Catalogue"}}),h("last_cipher",{kind:"cipher",inscription:`MODE: 2.10.2 / 8.8.2 / 2.3.6 / 7.4.1 / 3.7.1 / 6.1.2 / 5.8.3 / 8.5.4
REPLY: 1.11.2 / 4.3.5 / 2.2.4 / 6.6.5 / 4.3.3 / 2.9.6 / 1.5.3 / 4.9.2`,fields:[{id:"mode",label:"Mode word"},{id:"reply",label:"Reply word"}],solution:{mode:"together",reply:"tomorrow"}}),h("last_balance",{kind:"balance",fields:[{id:"house",label:"Household envelope",min:0,max:90,suffix:"minutes"},{id:"ward",label:"Hospital envelope",min:0,max:90,suffix:"minutes"},{id:"threshold",label:"Threshold envelope",min:0,max:90,suffix:"minutes"},{id:"common",label:"Common envelope",min:0,max:90,suffix:"minutes"},{id:"return",label:"Return envelope",min:0,max:90,suffix:"minutes"}],equations:["The five envelopes together contain the 90 minutes already held in the gate’s escrow.","The Hospital envelope exceeds the Return envelope by 8 minutes.","The Common envelope is twice the Return envelope.","The Household and Hospital envelopes together equal the Threshold envelope.","The Threshold envelope equals the Common and Return envelopes together."],solution:{house:"12",ward:"18",threshold:"30",common:"20",return:"10"}}),h("last_sequence",{kind:"sequence",cards:[{id:"choice",title:"Leave the choice open",description:"The final decision waits until every account is readable."},{id:"refund",title:"Restore conditional pledges",description:"Offered minutes remain attached to living owners."},{id:"original",title:"Read the original entry",description:"A person’s name survives even if its paper has been copied."},{id:"pool",title:"Authorize a shared account",description:"Only freely offered surplus can enter; a last reserve cannot be assumed spare."},{id:"protect",title:"Seal protected reserves",description:"A pledge does not surrender its owner’s protected reserve."},{id:"declare",title:"Publish the total",description:"Publish the sum without broadcasting private names."},{id:"copies",title:"Mark the copied entries",description:"Mirrored certificates describe one minute twice."}],solution:["original","copies","protect","refund","declare","pool","choice"]}),h("last_route",{kind:"route",width:7,height:7,blocked:[0,1,2,7,8,9,10,14,15,19,21,22,24,31,32,33,36,37,38,40,43,44,45,46],start:42,end:6,waypoints:[30,16,25,5],maxSteps:16,solution:[42,35,28,29,30,23,16,17,18,25,26,27,20,13,12,5,6]}),h("last_circuit",{kind:"circuit",size:5,initial:y([1,4,5,9,11,13,15,19,20,23]),target:[...c],solution:[1,4,5,9,11,13,15,19,20,23]})],conclusion:d(`The ledger is readable. Protected reserves stay attached to living owners. Conditional offers can be released without calling a person's disappearance a completed payment. The ninety minutes cannot disguise a theft as a gift merely by passing through the Lady's dissolving kiss.

The gate can now hear more than one future. You may attempt a common account, cross together into the country without measures, or return to finite days beside the patched bench. No choice repairs the roof by itself. None recalls the people already taken to the Hospital. Your friends will be here to answer you, with the small remainder of their time still their own. Supine waits too, in a container somebody else has to carry.`)}],V=[...q,...D,...Y].sort((e,t)=>e.act-t.act),G=e=>`case_${e}_done`,U={library_identity:"missing_tomorrow",museum_arrival:"abundance_audit",supine_wish:"portrait_testimony",supine_banishment:"portrait_testimony",hospital_provision:"continuity_patient",castle_minders:"listening_castle",infinite_open:"common_tomorrow"};function z(e,t){if(!e)return null;const a=U[e];return a&&!t.includes(a)?a:(e==="infinite_question"||e.startsWith("ending_"))&&V.find(n=>!t.includes(n.id))?.id||null}function K(e,t){return!!(t?.finished&&e.challenges.length===6&&e.challenges.every(a=>{const n=t.challenges[a.id];return n?.solved&&T(a.board,n)}))}export{V as I,G as a,T as b,K as c,z as r,u as t};
